def sort_colors(nums: list[int]) -> None:
    """Sorts 0s, 1s and 2s in place in one pass."""
    lo, i, hi = 0, 0, len(nums) - 1  # nums[:lo] are 0, nums[lo:i] are 1, nums[hi+1:] are 2
    while i <= hi:
        if nums[i] == 0:
            nums[lo], nums[i] = nums[i], nums[lo]
            lo += 1
            i += 1
        elif nums[i] == 2:
            nums[i], nums[hi] = nums[hi], nums[i]
            hi -= 1  # i stays: the value swapped in is not checked yet
        else:
            i += 1

