// Sorts 0s, 1s and 2s in place in one pass.
void sortColors(vector<int>& nums) {
    int lo = 0, i = 0, hi = (int)nums.size() - 1;  // [0, lo) are 0, [lo, i) are 1, (hi, n) are 2
    while (i <= hi) {
        if (nums[i] == 0) swap(nums[lo++], nums[i++]);
        else if (nums[i] == 2) swap(nums[i], nums[hi--]);  // i stays: the value swapped in is not checked yet
        else i++;
    }
}

