// sortColors sorts 0s, 1s and 2s in place in one pass.
func sortColors(nums []int) {
	lo, i, hi := 0, 0, len(nums)-1 // [0, lo) are 0, [lo, i) are 1, (hi, n) are 2
	for i <= hi {
		switch nums[i] {
		case 0:
			nums[lo], nums[i] = nums[i], nums[lo]
			lo++
			i++
		case 2:
			nums[i], nums[hi] = nums[hi], nums[i]
			hi-- // i stays: the value swapped in is not checked yet
		default:
			i++
		}
	}
}

