def first_missing_positive(nums: list[int]) -> int:
    """Smallest positive integer not in nums, in O(1) extra space."""
    n = len(nums)
    for i in range(n):
        # Swap nums[i] home to index v - 1 until it is out of range or already there.
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            v = nums[i]
            nums[i], nums[v - 1] = nums[v - 1], v
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

