// firstMissingPositive returns the smallest positive integer not in nums, in O(1) extra space.
func firstMissingPositive(nums []int) int {
	n := len(nums)
	for i := range nums {
		// Swap nums[i] home to index v - 1 until it is out of range or already there.
		for nums[i] >= 1 && nums[i] <= n && nums[nums[i]-1] != nums[i] {
			v := nums[i]
			nums[i], nums[v-1] = nums[v-1], v
		}
	}
	for i, v := range nums {
		if v != i+1 {
			return i + 1
		}
	}
	return n + 1
}

