// Largest sum of a non-empty contiguous subarray.
long long maxSubarray(const vector<int>& nums) {
    long long best = nums[0], cur = nums[0];  // cur: best sum of a subarray ending here
    for (size_t i = 1; i < nums.size(); i++) {
        cur = max<long long>(nums[i], cur + nums[i]);  // extend, or start over
        best = max(best, cur);
    }
    return best;
}

