// Words grouped by anagram class, groups in order of first appearance.
vector<vector<string>> groupAnagrams(const vector<string>& words) {
    unordered_map<string, int> index;  // canonical key -> position of its group
    vector<vector<string>> groups;
    for (const string& w : words) {
        string key = w;
        sort(key.begin(), key.end());  // anagrams share their sorted letters
        auto [it, fresh] = index.try_emplace(key, (int)groups.size());
        if (fresh) groups.emplace_back();
        groups[it->second].push_back(w);
    }
    return groups;
}

code.java:
class Solution {
    // Words grouped by anagram class, groups in order of first appearance.
    List<List<String>> groupAnagrams(String[] words) {
        Map<String, List<String>> groups = new LinkedHashMap<>(); // canonical key -> its words, in first-seen order
        for (String w : words) {
            char[] letters = w.toCharArray();
            Arrays.sort(letters); // anagrams share their sorted letters
            groups.computeIfAbsent(new String(letters), k -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }
}

