import "sort"

// groupAnagrams returns the words grouped by anagram class, in order of first appearance.
func groupAnagrams(words []string) [][]string {
	index := map[string]int{} // canonical key -> position of its group
	var groups [][]string
	for _, w := range words {
		letters := []byte(w)
		sort.Slice(letters, func(i, j int) bool { return letters[i] < letters[j] })
		key := string(letters) // anagrams share their sorted letters
		at, ok := index[key]
		if !ok {
			at = len(groups)
			index[key] = at
			groups = append(groups, nil)
		}
		groups[at] = append(groups[at], w)
	}
	return groups
}

