def longest_consecutive(nums: list[int]) -> int:
    """Length of the longest run of consecutive integers, in O(n)."""
    have = set(nums)
    best = 0
    for x in have:
        if x - 1 in have:
            continue  # not a run start: the run is counted from its start
        y = x
        while y + 1 in have:
            y += 1
        best = max(best, y - x + 1)
    return best

