// Length of the longest run of consecutive integers, in O(n).
int longestConsecutive(const vector<int>& nums) {
    unordered_set<int> have(nums.begin(), nums.end());
    int best = 0;
    for (int x : have) {
        if (have.count(x - 1)) continue;  // not a run start: the run is counted from its start
        int y = x;
        while (have.count(y + 1)) y++;
        best = max(best, y - x + 1);
    }
    return best;
}

