class Solution {
    // Length of the longest run of consecutive integers, in O(n).
    int longestConsecutive(int[] nums) {
        Set<Integer> have = new HashSet<>();
        for (int x : nums) have.add(x);
        int best = 0;
        for (int x : have) {
            if (have.contains(x - 1)) continue; // not a run start: the run is counted from its start
            int y = x;
            while (have.contains(y + 1)) y++;
            best = Math.max(best, y - x + 1);
        }
        return best;
    }
}

