// longestConsecutive returns the length of the longest run of consecutive integers, in O(n).
func longestConsecutive(nums []int) int {
	have := map[int]bool{}
	for _, x := range nums {
		have[x] = true
	}
	best := 0
	for x := range have {
		if have[x-1] {
			continue // not a run start: the run is counted from its start
		}
		y := x
		for have[y+1] {
			y++
		}
		best = max(best, y-x+1)
	}
	return best
}

