// Start of every occurrence of a non-empty pat, found with rolling hashes.
vector<int> rabinKarp(const string& text, const string& pat) {
    const long long MOD = 1000000007, BASE = 131;
    int n = text.size(), m = pat.size();
    if (m > n) return {};
    long long top = 1, hp = 0, hw = 0;  // top: weight of the character leaving the window
    for (int i = 1; i < m; i++) top = top * BASE % MOD;
    for (int i = 0; i < m; i++) {
        hp = (hp * BASE + pat[i]) % MOD;
        hw = (hw * BASE + text[i]) % MOD;
    }
    vector<int> res;
    for (int i = 0; i + m <= n; i++) {
        if (hw == hp && text.compare(i, m, pat) == 0) res.push_back(i);  // confirm a hit: hashes can collide
        if (i + m < n)  // roll: drop text[i], add text[i + m]
            hw = ((hw - text[i] * top % MOD + MOD) % MOD * BASE + text[i + m]) % MOD;
    }
    return res;
}

