class Solution {
    // Start of every occurrence of a non-empty pat, found with rolling hashes.
    List<Integer> rabinKarp(String text, String pat) {
        final long MOD = 1_000_000_007L, BASE = 131;
        int n = text.length(), m = pat.length();
        List<Integer> res = new ArrayList<>();
        if (m > n) return res;
        long top = 1, hp = 0, hw = 0; // top: weight of the character leaving the window
        for (int i = 1; i < m; i++) top = top * BASE % MOD;
        for (int i = 0; i < m; i++) {
            hp = (hp * BASE + pat.charAt(i)) % MOD;
            hw = (hw * BASE + text.charAt(i)) % MOD;
        }
        for (int i = 0; i + m <= n; i++) {
            if (hw == hp && text.startsWith(pat, i)) res.add(i); // confirm a hit: hashes can collide
            if (i + m < n) // roll: drop text[i], add text[i + m]
                hw = ((hw - text.charAt(i) * top % MOD + MOD) % MOD * BASE + text.charAt(i + m)) % MOD;
        }
        return res;
    }
}

