// rabinKarp returns the start of every occurrence of a non-empty pat, found with rolling hashes.
func rabinKarp(text, pat string) []int {
	const mod, base = 1_000_000_007, 131
	n, m := len(text), len(pat)
	res := []int{}
	if m > n {
		return res
	}
	top, hp, hw := 1, 0, 0 // top: weight of the character leaving the window
	for i := 1; i < m; i++ {
		top = top * base % mod
	}
	for i := 0; i < m; i++ {
		hp = (hp*base + int(pat[i])) % mod
		hw = (hw*base + int(text[i])) % mod
	}
	for i := 0; i+m <= n; i++ {
		if hw == hp && text[i:i+m] == pat { // confirm a hit: hashes can collide
			res = append(res, i)
		}
		if i+m < n { // roll: drop text[i], add text[i + m]
			hw = ((hw-int(text[i])*top%mod+mod)%mod*base + int(text[i+m])) % mod
		}
	}
	return res
}

