def reverse_words(s: str) -> str:
    """Words in reverse order, single spaces between them, none at the ends."""
    chars = list(s)

    def reverse(i: int, j: int) -> None:  # chars[i..j] in place
        while i < j:
            chars[i], chars[j] = chars[j], chars[i]
            i, j = i + 1, j - 1

    w = i = 0  # w writes, i reads; chars[:w] is the squeezed result so far
    while i < len(chars):
        if chars[i] == " ":
            i += 1
            continue
        if w:
            chars[w] = " "  # one space before every word but the first
            w += 1
        start = w
        while i < len(chars) and chars[i] != " ":
            chars[w] = chars[i]
            w, i = w + 1, i + 1
        reverse(start, w - 1)  # each word backwards now...
    reverse(0, w - 1)  # ...so reversing it all leaves the words in reverse order, each readable
    return "".join(chars[:w])

