// Words in reverse order, single spaces between them, none at the ends.
string reverseWords(string s) {
    int w = 0;  // s[0, w) is the squeezed result so far
    for (int i = 0; i < (int)s.size();) {
        if (s[i] == ' ') {
            i++;
            continue;
        }
        if (w) s[w++] = ' ';  // one space before every word but the first
        int start = w;
        while (i < (int)s.size() && s[i] != ' ') s[w++] = s[i++];
        reverse(s.begin() + start, s.begin() + w);  // each word backwards now...
    }
    s.resize(w);
    reverse(s.begin(), s.end());  // ...so reversing it all leaves the words in reverse order, each readable
    return s;
}

