class Solution {
    // Words in reverse order, single spaces between them, none at the ends.
    String reverseWords(String text) {
        char[] s = text.toCharArray();
        int w = 0; // s[0, w) is the squeezed result so far
        for (int i = 0; i < s.length;) {
            if (s[i] == ' ') {
                i++;
                continue;
            }
            if (w > 0) s[w++] = ' '; // one space before every word but the first
            int start = w;
            while (i < s.length && s[i] != ' ') s[w++] = s[i++];
            reverse(s, start, w - 1); // each word backwards now...
        }
        reverse(s, 0, w - 1); // ...so reversing it all leaves the words in reverse order, each readable
        return new String(s, 0, w);
    }

    private void reverse(char[] s, int i, int j) {
        for (; i < j; i++, j--) {
            char t = s[i];
            s[i] = s[j];
            s[j] = t;
        }
    }
}

