// reverseWords returns the words in reverse order, single spaces between them, none at the ends.
func reverseWords(text string) string {
	s := []byte(text)
	reverse := func(i, j int) { // s[i..j] in place
		for ; i < j; i, j = i+1, j-1 {
			s[i], s[j] = s[j], s[i]
		}
	}
	w := 0 // s[:w] is the squeezed result so far
	for i := 0; i < len(s); {
		if s[i] == ' ' {
			i++
			continue
		}
		if w > 0 {
			s[w] = ' ' // one space before every word but the first
			w++
		}
		start := w
		for i < len(s) && s[i] != ' ' {
			s[w] = s[i]
			w, i = w+1, i+1
		}
		reverse(start, w-1) // each word backwards now...
	}
	reverse(0, w-1) // ...so reversing it all leaves the words in reverse order, each readable
	return string(s[:w])
}

