// Most vowels in any length-k substring (LC 1456).
int maxVowels(const string& s, int k) {
    auto vowel = [](char c) { return string("aeiou").find(c) != string::npos; };
    int cur = 0, best = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        cur += vowel(s[i]);  // s[i] enters the window
        if (i >= k) cur -= vowel(s[i - k]);  // s[i - k] leaves: the window is s[i-k+1..i]
        if (i >= k - 1) best = max(best, cur);  // only full windows count
    }
    return best;
}

