class Solution {
    // Most vowels in any length-k substring (LC 1456).
    int maxVowels(String s, int k) {
        int cur = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            if (vowel(s.charAt(i))) cur++; // s[i] enters the window
            if (i >= k && vowel(s.charAt(i - k))) cur--; // s[i - k] leaves: the window is s[i-k+1..i]
            if (i >= k - 1) best = Math.max(best, cur); // only full windows count
        }
        return best;
    }

    private boolean vowel(char c) {
        return "aeiou".indexOf(c) >= 0;
    }
}

