import "strings"

// maxVowels returns the most vowels in any length-k substring (LC 1456).
func maxVowels(s string, k int) int {
	vowel := func(c byte) int {
		if strings.IndexByte("aeiou", c) >= 0 {
			return 1
		}
		return 0
	}
	cur, best := 0, 0
	for i := 0; i < len(s); i++ {
		cur += vowel(s[i]) // s[i] enters the window
		if i >= k {
			cur -= vowel(s[i-k]) // s[i - k] leaves: the window is s[i-k+1..i]
		}
		if i >= k-1 { // only full windows count
			best = max(best, cur)
		}
	}
	return best
}

