// Most water two walls can hold (LC 11).
long long maxArea(const vector<int>& height) {
    int lo = 0, hi = (int)height.size() - 1;
    long long best = 0;
    while (lo < hi) {
        best = max(best, (long long)(hi - lo) * min(height[lo], height[hi]));
        if (height[lo] < height[hi]) lo++;  // the shorter wall caps every narrower pair it is in
        else hi--;
    }
    return best;
}

