// Subarrays with exactly k distinct values (LC 992).
long long subarraysWithKDistinct(const vector<int>& nums, int k) {
    auto atMost = [&](int k) {  // subarrays with at most k distinct values
        unordered_map<int, int> cnt;
        long long total = 0;
        for (int left = 0, right = 0; right < (int)nums.size(); right++) {
            if (++cnt[nums[right]] == 1) k--;
            while (k < 0)  // one distinct value too many: shrink from the left
                if (--cnt[nums[left++]] == 0) k++;
            total += right - left + 1;  // windows that end at right and start at or after left
        }
        return total;
    };
    return atMost(k) - atMost(k - 1);
}

