        Map<Integer, Integer> cnt = new HashMap<>();
        long total = 0;
        for (int left = 0, right = 0; right < nums.length; right++) {
            if (cnt.merge(nums[right], 1, Integer::sum) == 1) k--;
            while (k < 0) // one distinct value too many: shrink from the left
                if (cnt.merge(nums[left++], -1, Integer::sum) == 0) k++;
            total += right - left + 1; // windows that end at right and start at or after left
        }
        return total;
    }
}

