// subarraysWithKDistinct counts the subarrays with exactly k distinct values (LC 992).
func subarraysWithKDistinct(nums []int, k int) int {
	atMost := func(k int) int { // subarrays with at most k distinct values
		cnt := map[int]int{}
		left, total := 0, 0
		for right, x := range nums {
			cnt[x]++
			if cnt[x] == 1 {
				k--
			}
			for k < 0 { // one distinct value too many: shrink from the left
				cnt[nums[left]]--
				if cnt[nums[left]] == 0 {
					k++
				}
				left++
			}
			total += right - left + 1 // windows that end at right and start at or after left
		}
		return total
	}
	return atMost(k) - atMost(k-1)
}

