// n zeros, then each {l, r, v} adds v to positions l..r (LC 370).
vector<long long> rangeAdd(int n, const vector<array<int, 3>>& updates) {
    vector<long long> diff(n + 1, 0);  // diff[i] = a[i] - a[i - 1]; the extra slot takes r + 1 = n
    for (auto [l, r, v] : updates) {
        diff[l] += v;
        diff[r + 1] -= v;  // the change stops after r
    }
    vector<long long> res(n);
    long long run = 0;
    for (int i = 0; i < n; i++) res[i] = run += diff[i];  // prefix sums rebuild the array
    return res;
}

