func rangeAdd(n int, updates [][3]int) []int {
	diff := make([]int, n+1) // diff[i] = a[i] - a[i-1]; the extra slot takes r + 1 = n
	for _, u := range updates {
		diff[u[0]] += u[2]
		diff[u[1]+1] -= u[2] // the change stops after r
	}
	res := make([]int, n)
	run := 0
	for i := 0; i < n; i++ {
		run += diff[i] // prefix sums of the differences rebuild the array
		res[i] = run
	}
	return res
}

