// Matrix2D answers the sum of any sub-rectangle in O(1) after O(rows × cols) setup (LC 304).
type Matrix2D struct {
	pre [][]int // pre[r][c]: sum of the top-left r × c block
}

func NewMatrix2D(grid [][]int) *Matrix2D {
	rows, cols := len(grid), len(grid[0])
	pre := make([][]int, rows+1) // row 0 and column 0 stay zero
	for r := range pre {
		pre[r] = make([]int, cols+1)
	}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			pre[r+1][c+1] = pre[r][c+1] + pre[r+1][c] - pre[r][c] + grid[r][c]
		}
	}
	return &Matrix2D{pre}
}

// Sum takes corners (r1, c1) and (r2, c2), both inclusive.
func (m *Matrix2D) Sum(r1, c1, r2, c2 int) int {
	p := m.pre
	return p[r2+1][c2+1] - p[r1][c2+1] - p[r2+1][c1] + p[r1][c1]
}

