class Solution {
    // Union of closed intervals, by start; touching ones such as [1, 2] and [2, 3] merge.
    List<int[]> merge(int[][] intervals) {
        int[][] sorted = intervals.clone();
        Arrays.sort(sorted, Comparator.comparingInt(iv -> iv[0]));
        List<int[]> res = new ArrayList<>();
        for (int[] iv : sorted) {
            int[] last = res.isEmpty() ? null : res.get(res.size() - 1);
            if (last != null && iv[0] <= last[1]) last[1] = Math.max(last[1], iv[1]); // overlaps the last merged interval
            else res.add(new int[] {iv[0], iv[1]});
        }
        return res;
    }
}

