def min_speed(piles: list[int], hours: int) -> int:
    """Smallest eating speed that finishes every pile within hours (LC 875)."""

    def ok(speed: int) -> bool:  # monotone: a faster speed never needs more hours
        return sum((p - 1) // speed + 1 for p in piles) <= hours

    lo, hi = 1, max(piles)  # the answer is in [lo, hi]; hi always works
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid  # mid works: the answer is mid or smaller
        else:
            lo = mid + 1
    return lo

