        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(piles, hours, mid)) hi = mid; // mid works: the answer is mid or smaller
            else lo = mid + 1;
        }
        return lo;
    }

    // Monotone: a faster speed never needs more hours.
    private boolean ok(int[] piles, long hours, int speed) {
        long need = 0;
        for (int p : piles) need += (p - 1) / speed + 1;
        return need <= hours;
    }
