// minSpeed returns the smallest eating speed that finishes every pile within hours (LC 875).
func minSpeed(piles []int, hours int) int {
	ok := func(speed int) bool { // monotone: a faster speed never needs more hours
		need := 0
		for _, p := range piles {
			need += (p-1)/speed + 1
		}
		return need <= hours
	}
	lo, hi := 1, slices.Max(piles) // the answer is in [lo, hi]
	for lo < hi {
		mid := lo + (hi-lo)/2
		if ok(mid) {
			hi = mid // mid works: the answer is mid or smaller
		} else {
			lo = mid + 1
		}
	}
	return lo
}

