from collections import deque


def max_sliding_window(nums: list[int], k: int) -> list[int]:
    """Maximum of every length-k window (LC 239)."""
    dq: deque[int] = deque()  # indexes in the window, values decreasing front to back
    res = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()  # smaller values before x can never be a maximum again
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()  # the front slid out of the window
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

