// Maximum of every length-k window (LC 239).
vector<int> maxSlidingWindow(const vector<int>& nums, int k) {
    deque<int> dq;  // indexes in the window, values decreasing front to back
    vector<int> res;
    for (int i = 0; i < (int)nums.size(); i++) {
        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();  // they can never be a maximum again
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();  // the front slid out of the window
        if (i >= k - 1) res.push_back(nums[dq.front()]);
    }
    return res;
}

