class Solution {
    // Maximum of every length-k window (LC 239).
    int[] maxSlidingWindow(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>(); // indexes in the window, values decreasing front to back
        int[] res = new int[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast(); // they can never be a maximum again
            dq.offerLast(i);
            if (dq.peekFirst() <= i - k) dq.pollFirst(); // the front slid out of the window
            if (i >= k - 1) res[i - k + 1] = nums[dq.peekFirst()];
        }
        return res;
    }
}

