// maxSlidingWindow returns the maximum of every length-k window (LC 239).
func maxSlidingWindow(nums []int, k int) []int {
	var dq []int // indexes in the window, values decreasing front to back
	var res []int
	for i, x := range nums {
		for len(dq) > 0 && nums[dq[len(dq)-1]] <= x {
			dq = dq[:len(dq)-1] // they can never be a maximum again
		}
		dq = append(dq, i)
		if dq[0] <= i-k {
			dq = dq[1:] // the front slid out of the window
		}
		if i >= k-1 {
			res = append(res, nums[dq[0]])
		}
	}
	return res
}

