import heapq


def kth_largest(nums: list[int], k: int) -> int:
    """The k-th largest value (LC 215), with a size-k min-heap."""
    heap: list[int] = []  # the k largest so far; heap[0] is the smallest of them
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)  # x beats the weakest of the top k
    return heap[0]

