int kthLargest(const vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> heap;  // the k largest so far; top is the smallest
    for (int x : nums) {
        if ((int)heap.size() < k) heap.push(x);
        else if (x > heap.top()) {
            heap.pop();  // x beats the weakest of the top k
            heap.push(x);
        }
