import "container/heap"

// minHeap is a min-heap of ints for container/heap.
type minHeap []int

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// kthLargest returns the k-th largest value (LC 215), with a size-k min-heap.
func kthLargest(nums []int, k int) int {
	h := &minHeap{} // the k largest so far; (*h)[0] is the smallest
	for _, x := range nums {
		if h.Len() < k {
			heap.Push(h, x)
		} else if x > (*h)[0] {
			(*h)[0] = x // x beats the weakest of the top k
			heap.Fix(h, 0)
		}
	}
	return (*h)[0]
}

