def calculate(s: str) -> int:
    """+ - * / over non-negative integers, no parentheses (LC 227); / truncates toward zero."""
    stack: list[int] = []  # signed terms to add up; * and / fold into the last one
    num, op = 0, "+"  # op: the operator before num
    for i, c in enumerate(s):
        if c.isdigit():
            num = num * 10 + int(c)
        if (not c.isdigit() and c != " ") or i == len(s) - 1:  # an operator or the end closes num
            if op == "+":
                stack.append(num)
            elif op == "-":
                stack.append(-num)
            elif op == "*":
                stack.append(stack.pop() * num)
            else:
                top = stack.pop()
                stack.append(abs(top) // num * (1 if top >= 0 else -1))  # truncate toward zero
            op, num = c, 0
    return sum(stack)

