func calculate(s string) int {
	var stack []int // signed terms to add up; * and / fold into the last one
	num, op := 0, byte('+') // op: the operator before num
	for i := 0; i < len(s); i++ {
		c := s[i]
		digit := c >= '0' && c <= '9'
		if digit {
			num = num*10 + int(c-'0')
		}
		if (!digit && c != ' ') || i == len(s)-1 { // an operator or the end closes num
			switch op {
			case '+':
				stack = append(stack, num)
			case '-':
				stack = append(stack, -num)
			case '*':
				stack[len(stack)-1] *= num
			default:
				stack[len(stack)-1] /= num // Go division truncates toward zero
			}
			op, num = c, 0
		}
	}
	total := 0
	for _, term := range stack {
		total += term
	}
	return total
}

