// Fewest jumps from index 0 to the last; nums[i] is the longest jump from i (LC 45).
int minJumps(const vector<int>& nums) {
    int jumps = 0, end = 0, far = 0;  // indexes up to end take `jumps` jumps; far: the next jump's reach
    for (int i = 0; i + 1 < (int)nums.size(); i++) {
        far = max(far, i + nums[i]);
        if (i == end) {  // this jump's range is used up: take another
            jumps++;
            end = far;
        }
    }
    return jumps;
}

