// Most courses {duration, last day} you can finish one at a time (LC 630).
int scheduleCourse(vector<pair<int, int>> courses) {
    sort(courses.begin(), courses.end(), [](auto& a, auto& b) { return a.second < b.second; });  // earliest deadline first
    priority_queue<int> taken;  // chosen durations, longest on top
    long long day = 0;
    for (auto [duration, last] : courses) {
        taken.push(duration);
        day += duration;
        if (day > last) {  // past the deadline: drop the longest course taken so far
            day -= taken.top();
            taken.pop();
        }
    }
    return taken.size();
}

