    int scheduleCourse(int[][] courses) {
        int[][] sorted = courses.clone();
        Arrays.sort(sorted, Comparator.comparingInt(c -> c[1])); // earliest deadline first
        PriorityQueue<Integer> taken = new PriorityQueue<>(Comparator.reverseOrder()); // longest on top
        long day = 0;
        for (int[] c : sorted) {
            taken.offer(c[0]);
            day += c[0];
            if (day > c[1]) day -= taken.poll(); // past the deadline: drop the longest course taken so far
        }
        return taken.size();
    }
}

