	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// scheduleCourse returns the most courses {duration, last day} you can finish one at a time (LC 630).
func scheduleCourse(courses [][2]int) int {
	sorted := append([][2]int(nil), courses...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i][1] < sorted[j][1] }) // earliest deadline first
	taken := &maxHeap{} // chosen durations, longest on top
	day := 0
	for _, c := range sorted {
		heap.Push(taken, c[0])
		day += c[0]
		if day > c[1] { // past the deadline: drop the longest course taken so far
			day -= heap.Pop(taken).(int)
		}
	}
	return taken.Len()
}

