struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v, ListNode* n = nullptr) : val(v), next(n) {}
};

// Reverses every full group of k nodes; a shorter tail stays as it is (LC 25).
ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode dummy(0, head);
    ListNode* prev = &dummy;  // the node before the group being reversed
    while (true) {
        ListNode* tail = prev;
        for (int i = 0; i < k; i++) {  // is there a full group after prev?
            tail = tail->next;
            if (!tail) return dummy.next;
        }
        ListNode *nxt = tail->next, *cur = prev->next, *p = nxt;
        while (cur != nxt) {  // reverse prev->next..tail, hanging it onto nxt
            ListNode* after = cur->next;
            cur->next = p;
            p = cur;
            cur = after;
        }
        ListNode* first = prev->next;  // the group's old first node is now its last
        prev->next = tail;
        prev = first;
    }
}

