func reverseKGroup(head *ListNode, k int) *ListNode {
	dummy := &ListNode{0, head}
	prev := dummy // the node before the group being reversed
	for {
		tail := prev
		for i := 0; i < k; i++ { // is there a full group after prev?
			tail = tail.Next
			if tail == nil {
