// Root, left, right without recursion (LC 144).
vector<int> preorder(TreeNode* root) {
    vector<int> res;
    vector<TreeNode*> stack;
    if (root) stack.push_back(root);
    while (!stack.empty()) {
        TreeNode* node = stack.back();
        stack.pop_back();
        res.push_back(node->val);
        if (node->right) stack.push_back(node->right);  // pushed first, so it comes out after the left subtree
        if (node->left) stack.push_back(node->left);
    }
    return res;
}

// Left, right, root: a root, right, left walk reversed (LC 145).
vector<int> postorder(TreeNode* root) {
    vector<int> res;
    vector<TreeNode*> stack;
    if (root) stack.push_back(root);
    while (!stack.empty()) {
        TreeNode* node = stack.back();
        stack.pop_back();
        res.push_back(node->val);
        if (node->left) stack.push_back(node->left);
        if (node->right) stack.push_back(node->right);
    }
    reverse(res.begin(), res.end());
    return res;
}

