struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) : val(v), left(l), right(r) {}
};

// Downward paths, starting and ending anywhere, whose values sum to target (LC 437).
int pathSumCount(TreeNode* root, long long target) {
    unordered_map<long long, int> seen{{0, 1}};  // prefix sums on the current root-to-node path
    int count = 0;
    function<void(TreeNode*, long long)> dfs = [&](TreeNode* node, long long pre) {
        if (!node) return;
        pre += node->val;
        if (auto it = seen.find(pre - target); it != seen.end()) count += it->second;  // starts after an ancestor's prefix
        seen[pre]++;
        dfs(node->left, pre);
        dfs(node->right, pre);
        seen[pre]--;  // leaving node: its prefix is off the path now
    };
    dfs(root, 0);
    return count;
}

