class Solution {
    private final Map<Long, Integer> seen = new HashMap<>(); // prefix sums on the current root-to-node path
    private int count;

    // Downward paths, starting and ending anywhere, whose values sum to target (LC 437).
    int pathSumCount(TreeNode root, long target) {
        seen.clear();
        seen.put(0L, 1);
        count = 0;
        dfs(root, 0, target);
        return count;
    }

    private void dfs(TreeNode node, long pre, long target) {
        if (node == null) return;
        pre += node.val;
        count += seen.getOrDefault(pre - target, 0); // a path ending here starts after an ancestor's prefix
        seen.merge(pre, 1, Integer::sum);
        dfs(node.left, pre, target);
        dfs(node.right, pre, target);
        seen.merge(pre, -1, Integer::sum); // leaving node: its prefix is off the path now
    }
}

