def build_from_post(inorder: list[int], postorder: list[int]):
    """Rebuild a tree with distinct values from its inorder and postorder walks (LC 106)."""
    pos = {v: i for i, v in enumerate(inorder)}  # value -> inorder index
    roots = reversed(postorder)  # backwards, postorder yields root, then right, then left

    def build(lo: int, hi: int):  # the subtree whose inorder range is [lo, hi)
        if lo == hi:
            return None
        root = TreeNode(next(roots))
        mid = pos[root.val]
        root.right = build(mid + 1, hi)  # right first, matching the reversed postorder
        root.left = build(lo, mid)
        return root

    return build(0, len(inorder))

