// Rebuild a tree with distinct values from its inorder and postorder walks (LC 106).
TreeNode* buildFromPost(const vector<int>& inorder, const vector<int>& postorder) {
    unordered_map<int, int> pos;  // value -> inorder index
    for (int i = 0; i < (int)inorder.size(); i++) pos[inorder[i]] = i;
    int next = (int)postorder.size() - 1;  // backwards, postorder yields root, then right, then left
    function<TreeNode*(int, int)> build = [&](int lo, int hi) -> TreeNode* {  // inorder range [lo, hi)
        if (lo == hi) return nullptr;
        TreeNode* root = new TreeNode(postorder[next--]);
        int mid = pos[root->val];
        root->right = build(mid + 1, hi);  // right first, matching the reversed postorder
        root->left = build(lo, mid);
        return root;
    };
    return build(0, inorder.size());
}

