class Solution {
    private final Map<Integer, Integer> pos = new HashMap<>(); // value -> inorder index
    private int[] postorder;
    private int next;

    // Rebuild a tree with distinct values from its inorder and postorder walks (LC 106).
    TreeNode buildFromPost(int[] inorder, int[] postorder) {
        pos.clear();
        for (int i = 0; i < inorder.length; i++) pos.put(inorder[i], i);
        this.postorder = postorder;
        next = postorder.length - 1; // backwards, postorder yields root, then right, then left
        return build(0, inorder.length);
    }

    // The subtree whose inorder range is [lo, hi).
    private TreeNode build(int lo, int hi) {
        if (lo == hi) return null;
        TreeNode root = new TreeNode(postorder[next--]);
        int mid = pos.get(root.val);
        root.right = build(mid + 1, hi); // right first, matching the reversed postorder
        root.left = build(lo, mid);
        return root;
    }
}

