func buildFromPost(inorder, postorder []int) *TreeNode {
	pos := map[int]int{} // value -> inorder index
	for i, v := range inorder {
		pos[v] = i
	}
	next := len(postorder) - 1 // backwards, postorder yields root, then right, then left
	var build func(lo, hi int) *TreeNode // the subtree whose inorder range is [lo, hi)
	build = func(lo, hi int) *TreeNode {
		if lo == hi {
			return nil
		}
		root := &TreeNode{Val: postorder[next]}
		next--
		mid := pos[root.Val]
		root.Right = build(mid+1, hi) // right first, matching the reversed postorder
		root.Left = build(lo, mid)
		return root
	}
	return build(0, len(inorder))
}

