        self.val, self.left, self.right = val, left, right

def max_tree(nums: list[int]):
    """Maximum binary tree of distinct nums (LC 654), built in O(n)."""
    stack = []  # the right spine of the tree so far, values decreasing
    for x in nums:
        node = TreeNode(x)
        while stack and stack[-1].val < x:
            node.left = stack.pop()  # smaller nodes before x end up in its left subtree
        if stack:
            stack[-1].right = node  # x hangs right of the nearest larger value before it
        stack.append(node)
    return stack[0] if stack else None

