TreeNode* maxTree(const vector<int>& nums) {
    vector<TreeNode*> stack;  // the right spine of the tree so far, values decreasing
    for (int x : nums) {
        TreeNode* node = new TreeNode(x);
        while (!stack.empty() && stack.back()->val < x) {
            node->left = stack.back();  // smaller nodes before x end up in its left subtree
            stack.pop_back();
