    TreeNode maxTree(int[] nums) {
        Deque<TreeNode> stack = new ArrayDeque<>(); // the right spine of the tree so far, values decreasing
        for (int x : nums) {
            TreeNode node = new TreeNode(x);
            while (!stack.isEmpty() && stack.peek().val < x)
                node.left = stack.pop(); // smaller nodes before x end up in its left subtree
            if (!stack.isEmpty()) stack.peek().right = node; // x hangs right of the nearest larger value
            stack.push(node);
        }
        return stack.isEmpty() ? null : stack.peekLast();
    }
}

