	var stack []*TreeNode // the right spine of the tree so far, values decreasing
	for _, x := range nums {
		node := &TreeNode{Val: x}
		for len(stack) > 0 && stack[len(stack)-1].Val < x {
			node.Left = stack[len(stack)-1] // smaller nodes before x end up in its left subtree
			stack = stack[:len(stack)-1]
