def is_valid_bst(root) -> bool:
    """Every node lies strictly inside the bounds its ancestors set (LC 98)."""

    def ok(node, lo, hi) -> bool:  # node.val must be in the open range (lo, hi)
        if not node:
            return True
        if not lo < node.val < hi:
            return False
        return ok(node.left, lo, node.val) and ok(node.right, node.val, hi)

    return ok(root, float("-inf"), float("inf"))

