def delete_node(root, key: int):
    """The BST without key, if it was there (LC 450)."""
    if not root:
        return None
    if key < root.val:
        root.left = delete_node(root.left, key)
    elif key > root.val:
        root.right = delete_node(root.right, key)
    else:
        if not root.left or not root.right:  # zero or one child: lift it up
            return root.left or root.right
        succ = root.right  # two children: take the inorder successor's value...
        while succ.left:
            succ = succ.left
        root.val = succ.val
        root.right = delete_node(root.right, succ.val)  # ...and delete it below
    return root

