// {number of islands, largest island area} in a 0/1 grid (LC 200, LC 695).
pair<int, int> islandStats(const vector<vector<int>>& grid) {
    int rows = grid.size(), cols = grid[0].size(), count = 0, best = 0;
    vector<vector<bool>> seen(rows, vector<bool>(cols, false));
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] != 1 || seen[r][c]) continue;
            count++;
            int area = 0;
            vector<pair<int, int>> stack{{r, c}};
            seen[r][c] = true;
            while (!stack.empty()) {  // an explicit stack: no recursion limit on big islands
                auto [i, j] = stack.back();
                stack.pop_back();
                area++;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == 1 && !seen[ni][nj]) {
                        seen[ni][nj] = true;  // mark on push: no cell goes in twice
                        stack.push_back({ni, nj});
                    }
                }
            }
            best = max(best, area);
        }
    return {count, best};
}

