// islandStats returns the number of islands and the largest island area in a 0/1 grid.
func islandStats(grid [][]int) (int, int) {
	rows, cols := len(grid), len(grid[0])
	seen := make([][]bool, rows)
	for r := range seen {
		seen[r] = make([]bool, cols)
	}
	count, best := 0, 0
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if grid[r][c] != 1 || seen[r][c] {
				continue
			}
			count++
			area := 0
			stack := [][2]int{{r, c}}
			seen[r][c] = true
			for len(stack) > 0 { // an explicit stack: no recursion limit on big islands
				cell := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				area++
				for _, d := range dirs {
					ni, nj := cell[0]+d[0], cell[1]+d[1]
					if ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == 1 && !seen[ni][nj] {
						seen[ni][nj] = true // mark on push: no cell goes in twice
						stack = append(stack, [2]int{ni, nj})
					}
				}
			}
			best = max(best, area)
		}
	}
	return count, best
}

