// Fewest steps from top-left to bottom-right, breaking at most k walls (LC 1293).
int shortestWithBreaks(const vector<vector<int>>& grid, int k) {
    int rows = grid.size(), cols = grid[0].size();
    vector<vector<int>> best(rows, vector<int>(cols, -1));  // most breaks still in hand on reaching a cell
    best[0][0] = k;
    queue<array<int, 3>> q;  // a state is {r, c, breaks left}
    q.push({0, 0, k});
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int steps = 0; !q.empty(); steps++)
        for (int n = q.size(); n > 0; n--) {  // one BFS level per step
            auto [r, c, left] = q.front();
            q.pop();
            if (r == rows - 1 && c == cols - 1) return steps;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                int rest = left - grid[nr][nc];
                if (rest > best[nr][nc]) {  // more breaks left than any earlier visit: worth it
                    best[nr][nc] = rest;
                    q.push({nr, nc, rest});
                }
            }
        }
    return -1;
}

