class Solution {
    // Fewest steps from top-left to bottom-right, breaking at most k walls (LC 1293).
    int shortestWithBreaks(int[][] grid, int k) {
        int rows = grid.length, cols = grid[0].length;
        int[][] best = new int[rows][cols]; // most breaks still in hand on reaching a cell
        for (int[] row : best) Arrays.fill(row, -1);
        best[0][0] = k;
        Deque<int[]> q = new ArrayDeque<>(); // a state is {r, c, breaks left}
        q.offer(new int[] {0, 0, k});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int steps = 0; !q.isEmpty(); steps++)
            for (int n = q.size(); n > 0; n--) { // one BFS level per step
                int[] s = q.poll();
                if (s[0] == rows - 1 && s[1] == cols - 1) return steps;
                for (int[] d : dirs) {
                    int nr = s[0] + d[0], nc = s[1] + d[1];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    int rest = s[2] - grid[nr][nc];
                    if (rest > best[nr][nc]) { // more breaks left than any earlier visit: worth it
                        best[nr][nc] = rest;
                        q.offer(new int[] {nr, nc, rest});
                    }
                }
            }
        return -1;
    }
}

