// shortestWithBreaks returns the fewest steps from top-left to bottom-right, breaking at most k walls.
func shortestWithBreaks(grid [][]int, k int) int {
	rows, cols := len(grid), len(grid[0])
	best := make([][]int, rows) // most breaks still in hand on reaching a cell
	for r := range best {
		best[r] = make([]int, cols)
		for c := range best[r] {
			best[r][c] = -1
		}
	}
	best[0][0] = k
	q := [][3]int{{0, 0, k}} // a state is {r, c, breaks left}
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for steps := 0; len(q) > 0; steps++ {
		var next [][3]int // the following BFS level
		for _, s := range q {
			if s[0] == rows-1 && s[1] == cols-1 {
				return steps
			}
			for _, d := range dirs {
				nr, nc := s[0]+d[0], s[1]+d[1]
				if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
					continue
				}
				if rest := s[2] - grid[nr][nc]; rest > best[nr][nc] { // more breaks left than before: worth it
					best[nr][nc] = rest
					next = append(next, [3]int{nr, nc, rest})
				}
			}
		}
		q = next
	}
	return -1
}

