def is_bipartite(graph: list[list[int]]) -> bool:
    """Can the nodes be 2-coloured so every edge joins different colours? (LC 785)"""
    color = [-1] * len(graph)
    for s in range(len(graph)):  # every component, not only the one holding node 0
        if color[s] != -1:
            continue
        color[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1  # the other colour
                    q.append(v)
                elif color[v] == color[u]:
                    return False  # an odd cycle
    return True

