def critical_connections(n: int, connections: list[list[int]]) -> list[list[int]]:
    """Every bridge, an edge whose removal disconnects the graph (LC 1192)."""
    graph = [[] for _ in range(n)]
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)
    disc = [0] * n  # discovery time; 0 = not visited yet
    low = [0] * n  # earliest discovery time the subtree reaches with one back edge
    timer = 1
    res = []

    def dfs(u: int, parent: int) -> None:
        nonlocal timer
        disc[u] = low[u] = timer
        timer += 1
        for v in graph[u]:
            if v == parent:
                continue  # assumes no parallel edges
            if disc[v]:
                low[u] = min(low[u], disc[v])  # a back edge
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:  # v's subtree cannot climb above u without this edge
                    res.append([u, v])

    for s in range(n):
        if not disc[s]:
            dfs(s, -1)
    return res

