    private int[] disc, low; // disc 0 = not visited; low: earliest time reached with one back edge
    private int timer;
    private List<int[]> res;

    // Every bridge, an edge whose removal disconnects the graph (LC 1192).
    List<int[]> criticalConnections(int n, int[][] connections) {
