        low = new int[n];
        timer = 1;
        res = new ArrayList<>();
        for (int s = 0; s < n; s++)
            if (disc[s] == 0) dfs(s, -1);
        return res;
    }

    private void dfs(int u, int parent) {
        disc[u] = low[u] = timer++;
        for (int v : graph.get(u)) {
            if (v == parent) continue; // assumes no parallel edges
            if (disc[v] != 0) {
                low[u] = Math.min(low[u], disc[v]); // a back edge
            } else {
                dfs(v, u);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) res.add(new int[] {u, v}); // v's subtree cannot climb above u without this edge
            }
        }
    }
