def eventual_safe_nodes(graph: list[list[int]]) -> list[int]:
    """Nodes every path from which ends at a terminal node: no cycle is reachable (LC 802)."""
    WHITE, GRAY, BLACK = 0, 1, 2  # unvisited / on the current DFS path / finished and safe
    color = [WHITE] * len(graph)

    def safe(u: int) -> bool:
        if color[u] != WHITE:
            return color[u] == BLACK  # GRAY: back on the current path, so a cycle
        color[u] = GRAY
        if not all(safe(v) for v in graph[u]):
            return False  # stays GRAY: on a cycle or leading to one
        color[u] = BLACK
        return True

    return [u for u in range(len(graph)) if safe(u)]

