// eventualSafeNodes returns the nodes every path from which ends at a terminal node (LC 802).
func eventualSafeNodes(graph [][]int) []int {
	const (
		white = iota // unvisited
		gray         // on the current DFS path
		black        // finished and safe
	)
	color := make([]int, len(graph))
	var safe func(u int) bool
	safe = func(u int) bool {
		if color[u] != white {
			return color[u] == black // gray: back on the current path, so a cycle
		}
		color[u] = gray
		for _, v := range graph[u] {
			if !safe(v) {
				return false // stays gray: on a cycle or leading to one
			}
		}
		color[u] = black
		return true
	}
	res := []int{}
	for u := range graph {
		if safe(u) {
			res = append(res, u)
		}
	}
	return res
}

