// Courses 1..n, {a, b}: a before b, any number per term. Fewest terms, or -1 on a cycle (LC 1136).
int minSemesters(int n, const vector<pair<int, int>>& relations) {
    vector<vector<int>> graph(n + 1);
    vector<int> indeg(n + 1, 0), term(n + 1, 1);  // term[v]: the earliest term v can be taken
    for (auto [a, b] : relations) {
        graph[a].push_back(b);
        indeg[b]++;
    }
    queue<int> q;
    for (int v = 1; v <= n; v++)
        if (indeg[v] == 0) q.push(v);
    int done = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        done++;
        for (int v : graph[u]) {
            term[v] = max(term[v], term[u] + 1);  // DP in topological order: u is final when it leaves
            if (--indeg[v] == 0) q.push(v);
        }
    }
    return done == n ? *max_element(term.begin() + 1, term.end()) : -1;
}

