class Solution {
    // Courses 1..n, {a, b}: a before b, any number per term. Fewest terms, or -1 on a cycle (LC 1136).
    int minSemesters(int n, int[][] relations) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
        int[] indeg = new int[n + 1], term = new int[n + 1]; // term[v]: the earliest term v can be taken
        Arrays.fill(term, 1);
        for (int[] r : relations) {
            graph.get(r[0]).add(r[1]);
            indeg[r[1]]++;
        }
        Deque<Integer> q = new ArrayDeque<>();
        for (int v = 1; v <= n; v++)
            if (indeg[v] == 0) q.offer(v);
        int done = 0, best = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            done++;
            best = Math.max(best, term[u]);
            for (int v : graph.get(u)) {
                term[v] = Math.max(term[v], term[u] + 1); // DP in topological order: u is final when it leaves
                if (--indeg[v] == 0) q.offer(v);
            }
        }
        return done == n ? best : -1;
    }
}

