// minSemesters returns the fewest terms for courses 1..n ({a, b}: a before b), or -1 on a cycle.
func minSemesters(n int, relations [][2]int) int {
	graph := make([][]int, n+1)
	indeg, term := make([]int, n+1), make([]int, n+1) // term[v]: the earliest term v can be taken
	for _, r := range relations {
		graph[r[0]] = append(graph[r[0]], r[1])
		indeg[r[1]]++
	}
	var q []int
	for v := 1; v <= n; v++ {
		term[v] = 1
		if indeg[v] == 0 {
			q = append(q, v)
		}
	}
	done, best := 0, 0
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		done++
		best = max(best, term[u])
		for _, v := range graph[u] {
			term[v] = max(term[v], term[u]+1) // DP in topological order: u is final when it leaves
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	if done != n {
		return -1
	}
	return best
}

