def open_lock(deadends: list[str], target: str) -> int:
    """Fewest wheel turns from "0000" to target, never resting on a deadend (LC 752)."""
    dead = set(deadends)
    if "0000" in dead:
        return -1
    dist = {"0000": 0}  # every state seen so far, with its distance
    q = deque(["0000"])
    while q:
        s = q.popleft()
        if s == target:
            return dist[s]
        for i in range(4):
            for step in (1, -1):  # turn wheel i up or down
                t = s[:i] + str((int(s[i]) + step) % 10) + s[i + 1 :]
                if t not in dead and t not in dist:
                    dist[t] = dist[s] + 1
                    q.append(t)
    return -1

