        string s = q.front();
        q.pop();
        if (s == target) return dist[s];
        for (int i = 0; i < 4; i++)
            for (int step : {1, 9}) {  // turn wheel i up, or down (+9 is -1 mod 10)
                string t = s;
                t[i] = '0' + (s[i] - '0' + step) % 10;
                if (!dead.count(t) && !dist.count(t)) {
                    dist[t] = dist[s] + 1;
                    q.push(t);
                }
