class Solution {
    // Fewest wheel turns from "0000" to target, never resting on a deadend (LC 752).
    int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;
        Map<String, Integer> dist = new HashMap<>(Map.of("0000", 0)); // every state seen so far, with its distance
        Deque<String> q = new ArrayDeque<>(List.of("0000"));
        while (!q.isEmpty()) {
            String s = q.poll();
            if (s.equals(target)) return dist.get(s);
            for (int i = 0; i < 4; i++)
                for (int step : new int[] {1, 9}) { // turn wheel i up, or down (+9 is -1 mod 10)
                    char[] t = s.toCharArray();
                    t[i] = (char) ('0' + (t[i] - '0' + step) % 10);
                    String next = new String(t);
                    if (!dead.contains(next) && !dist.containsKey(next)) {
                        dist.put(next, dist.get(s) + 1);
                        q.offer(next);
                    }
                }
        }
        return -1;
    }
}

