// openLock returns the fewest wheel turns from "0000" to target, never resting on a deadend (LC 752).
func openLock(deadends []string, target string) int {
	dead := map[string]bool{}
	for _, d := range deadends {
		dead[d] = true
	}
	if dead["0000"] {
		return -1
	}
	dist := map[string]int{"0000": 0} // every state seen so far, with its distance
	q := []string{"0000"}
	for len(q) > 0 {
		s := q[0]
		q = q[1:]
		if s == target {
			return dist[s]
		}
		for i := 0; i < 4; i++ {
			for _, step := range []byte{1, 9} { // turn wheel i up, or down (+9 is -1 mod 10)
				t := []byte(s)
				t[i] = '0' + (t[i]-'0'+step)%10
				next := string(t)
				if _, seen := dist[next]; !seen && !dead[next] {
					dist[next] = dist[s] + 1
					q = append(q, next)
				}
			}
		}
	}
	return -1
}

