// Cheapest price from src to dst with at most k stops, i.e. k + 1 flights (LC 787).
long long cheapestWithin(int n, const vector<array<int, 3>>& flights, int src, int dst, int k) {
    const long long INF = LLONG_MAX / 4;
    vector<long long> dist(n, INF);
    dist[src] = 0;
    for (int round = 0; round <= k; round++) {  // after round i: best prices using at most i flights
        vector<long long> prev = dist;  // relax from last round only, so each round adds at most one flight
        for (auto [u, v, w] : flights)
            if (prev[u] + w < dist[v]) dist[v] = prev[u] + w;
    }
    return dist[dst] == INF ? -1 : dist[dst];
}

