    long cheapestWithin(int n, int[][] flights, int src, int dst, int k) {
        final long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int round = 0; round <= k; round++) { // after round i: best prices using at most i flights
            long[] prev = dist.clone(); // relax from last round only, so each round adds at most one flight
            for (int[] f : flights)
                if (prev[f[0]] + f[2] < dist[f[1]]) dist[f[1]] = prev[f[0]] + f[2];
        }
        return dist[dst] == INF ? -1 : dist[dst];
    }
}

