// cheapestWithin returns the cheapest price from src to dst with at most k stops (LC 787).
func cheapestWithin(n int, flights [][3]int, src, dst, k int) int {
	const inf = 1 << 60
	dist := make([]int, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[src] = 0
	for round := 0; round <= k; round++ { // after round i: best prices using at most i flights
		prev := append([]int(nil), dist...) // relax from last round only, so each round adds at most one flight
		for _, f := range flights {
			if prev[f[0]]+f[2] < dist[f[1]] {
				dist[f[1]] = prev[f[0]] + f[2]
			}
		}
	}
	if dist[dst] == inf {
		return -1
	}
	return dist[dst]
}

