// Length of the shortest walk that visits every node; edges may repeat (LC 847).
int shortestPathAllNodes(const vector<vector<int>>& graph) {
    int n = graph.size(), full = (1 << n) - 1;
    vector<vector<bool>> seen(n, vector<bool>(1 << n, false));  // state (node, mask of visited nodes)
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++) {  // every node is a start, at distance 0
        seen[i][1 << i] = true;
        q.push({i, 1 << i});
    }
    for (int steps = 0; !q.empty(); steps++)
        for (int k = q.size(); k > 0; k--) {
            auto [u, mask] = q.front();
            q.pop();
            if (mask == full) return steps;
            for (int v : graph[u]) {
                int next = mask | 1 << v;
                if (!seen[v][next]) {
                    seen[v][next] = true;
                    q.push({v, next});
                }
            }
        }
    return -1;
}

