    // Length of the shortest walk that visits every node; edges may repeat (LC 847).
    int shortestPathAllNodes(int[][] graph) {
        int n = graph.length, full = (1 << n) - 1;
        boolean[][] seen = new boolean[n][1 << n]; // state (node, mask of visited nodes)
        Deque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) { // every node is a start, at distance 0
            seen[i][1 << i] = true;
            q.offer(new int[] {i, 1 << i});
        }
        for (int steps = 0; !q.isEmpty(); steps++)
            for (int k = q.size(); k > 0; k--) {
                int[] state = q.poll();
                if (state[1] == full) return steps;
                for (int v : graph[state[0]]) {
                    int next = state[1] | 1 << v;
                    if (!seen[v][next]) {
                        seen[v][next] = true;
                        q.offer(new int[] {v, next});
                    }
                }
            }
        return -1;
    }
}

