// shortestPathAllNodes returns the length of the shortest walk that visits every node (LC 847).
func shortestPathAllNodes(graph [][]int) int {
	n := len(graph)
	full := 1<<n - 1
	seen := make([][]bool, n) // state (node, mask of visited nodes)
	var q [][2]int
	for i := range seen { // every node is a start, at distance 0
		seen[i] = make([]bool, 1<<n)
		seen[i][1<<i] = true
		q = append(q, [2]int{i, 1 << i})
	}
	for steps := 0; len(q) > 0; steps++ {
		var next [][2]int // the following BFS level
		for _, s := range q {
			if s[1] == full {
				return steps
			}
			for _, v := range graph[s[0]] {
				if mask := s[1] | 1<<v; !seen[v][mask] {
					seen[v][mask] = true
					next = append(next, [2]int{v, mask})
				}
			}
		}
		q = next
	}
	return -1
}

