// Minimum spanning tree weight of all points under Manhattan distance (LC 1584).
long long minCostConnect(const vector<pair<int, int>>& points) {
    int n = points.size();
    vector<long long> dist(n, LLONG_MAX);  // dist[v]: cheapest edge from the tree to v so far
    dist[0] = 0;
    vector<bool> inTree(n, false);
    long long total = 0;
    for (int round = 0; round < n; round++) {
        int u = -1;
        for (int v = 0; v < n; v++)  // nearest outside node
            if (!inTree[v] && (u < 0 || dist[v] < dist[u])) u = v;
        inTree[u] = true;
        total += dist[u];
        for (int v = 0; v < n; v++)
            if (!inTree[v]) {
                long long d = abs(points[u].first - points[v].first) + abs(points[u].second - points[v].second);
                dist[v] = min(dist[v], d);
            }
    }
    return total;
}

