func minCostConnect(points [][2]int) int {
	n := len(points)
	abs := func(x int) int {
		if x < 0 {
			return -x
		}
		return x
	}
	dist := make([]int, n) // dist[v]: cheapest edge from the tree to v so far
	for v := 1; v < n; v++ {
		dist[v] = 1 << 62
	}
	inTree := make([]bool, n)
	total := 0
	for round := 0; round < n; round++ {
		u := -1
		for v := 0; v < n; v++ { // nearest outside node
			if !inTree[v] && (u < 0 || dist[v] < dist[u]) {
				u = v
			}
		}
		inTree[u] = true
		total += dist[u]
		for v := 0; v < n; v++ {
			if !inTree[v] {
				d := abs(points[u][0]-points[v][0]) + abs(points[u][1]-points[v][1])
				dist[v] = min(dist[v], d)
			}
		}
	}
	return total
