def min_height_roots(n: int, edges: list[list[int]]) -> list[int]:
    """Roots giving the tree its minimum height (LC 310): the 1 or 2 nodes left after peeling leaves."""
    if n <= 2:
        return list(range(n))
    graph = [[] for _ in range(n)]
    deg = [0] * n
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        deg[u] += 1
        deg[v] += 1
    leaves = [u for u in range(n) if deg[u] == 1]
    left = n
    while left > 2:  # peel one whole layer of leaves at a time
        left -= len(leaves)
        nxt = []
        for leaf in leaves:
            for nb in graph[leaf]:
                deg[nb] -= 1
                if deg[nb] == 1:  # nb just became a leaf of the smaller tree
                    nxt.append(nb)
        leaves = nxt
    return sorted(leaves)

