// Roots giving the tree its minimum height (LC 310): the 1 or 2 nodes left after peeling leaves.
vector<int> minHeightRoots(int n, const vector<pair<int, int>>& edges) {
    if (n <= 2) {
        vector<int> all(n);
        iota(all.begin(), all.end(), 0);
        return all;
    }
    vector<vector<int>> graph(n);
    vector<int> deg(n, 0), leaves;
    for (auto [u, v] : edges) {
        graph[u].push_back(v);
        graph[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }
    for (int u = 0; u < n; u++)
        if (deg[u] == 1) leaves.push_back(u);
    for (int left = n; left > 2;) {  // peel one whole layer of leaves at a time
        left -= leaves.size();
        vector<int> next;
        for (int leaf : leaves)
            for (int nb : graph[leaf])
                if (--deg[nb] == 1) next.push_back(nb);  // nb just became a leaf of the smaller tree
        leaves = next;
    }
    sort(leaves.begin(), leaves.end());
    return leaves;
}

