class Solution {
    // Roots giving the tree its minimum height (LC 310): the 1 or 2 nodes left after peeling leaves.
    List<Integer> minHeightRoots(int n, int[][] edges) {
        List<Integer> leaves = new ArrayList<>();
        if (n <= 2) {
            for (int u = 0; u < n; u++) leaves.add(u);
            return leaves;
        }
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        int[] deg = new int[n];
        for (int[] e : edges) {
            graph.get(e[0]).add(e[1]);
            graph.get(e[1]).add(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }
        for (int u = 0; u < n; u++)
            if (deg[u] == 1) leaves.add(u);
        for (int left = n; left > 2;) { // peel one whole layer of leaves at a time
            left -= leaves.size();
            List<Integer> next = new ArrayList<>();
            for (int leaf : leaves)
                for (int nb : graph.get(leaf))
                    if (--deg[nb] == 1) next.add(nb); // nb just became a leaf of the smaller tree
            leaves = next;
        }
        Collections.sort(leaves);
        return leaves;
    }
}

