import "sort"

// minHeightRoots returns the roots giving the tree its minimum height (LC 310).
func minHeightRoots(n int, edges [][2]int) []int {
	if n <= 2 {
		all := make([]int, n)
		for i := range all {
			all[i] = i
		}
		return all
	}
	graph := make([][]int, n)
	deg := make([]int, n)
	for _, e := range edges {
		graph[e[0]] = append(graph[e[0]], e[1])
		graph[e[1]] = append(graph[e[1]], e[0])
		deg[e[0]]++
		deg[e[1]]++
	}
	var leaves []int
	for u := 0; u < n; u++ {
		if deg[u] == 1 {
			leaves = append(leaves, u)
		}
	}
	for left := n; left > 2; { // peel one whole layer of leaves at a time
		left -= len(leaves)
		var next []int
		for _, leaf := range leaves {
			for _, nb := range graph[leaf] {
				deg[nb]--
				if deg[nb] == 1 { // nb just became a leaf of the smaller tree
					next = append(next, nb)
				}
			}
		}
		leaves = next
	}
	sort.Ints(leaves)
	return leaves
}

