// Every subset of distinct nums.
vector<vector<int>> subsets(const vector<int>& nums) {
    vector<vector<int>> res;
    vector<int> path;
    function<void(int)> dfs = [&](int i) {
        if (i == (int)nums.size()) {
            res.push_back(path);  // one leaf per subset
            return;
        }
        dfs(i + 1);  // skip nums[i]
        path.push_back(nums[i]);
        dfs(i + 1);  // take nums[i]
        path.pop_back();
    };
    dfs(0);
    return res;
}

