    private final List<Integer> path = new ArrayList<>();
    private int[] nums;

    // Every subset of distinct nums.
    List<List<Integer>> subsets(int[] nums) {
        this.nums = nums;
        res.clear();
        dfs(0);
        return new ArrayList<>(res);
    }

    private void dfs(int i) {
        if (i == nums.length) {
            res.add(new ArrayList<>(path)); // one leaf per subset
            return;
        }
        dfs(i + 1); // skip nums[i]
        path.add(nums[i]);
        dfs(i + 1); // take nums[i]
        path.remove(path.size() - 1);
    }
}

