// Every balanced string of n pairs of parentheses (LC 22).
vector<string> generateParentheses(int n) {
    vector<string> res;
    string path;
    function<void(int, int)> dfs = [&](int opened, int closed) {
        if ((int)path.size() == 2 * n) {
            res.push_back(path);
            return;
        }
        if (opened < n) {  // an opening bracket fits while some are left
            path.push_back('(');
            dfs(opened + 1, closed);
            path.pop_back();
        }
        if (closed < opened) {  // a closing bracket needs an unmatched opening one
            path.push_back(')');
            dfs(opened, closed + 1);
            path.pop_back();
        }
    };
    dfs(0, 0);
    return res;
}

