    private final StringBuilder path = new StringBuilder();
    private int n;

    // Every balanced string of n pairs of parentheses (LC 22).
    List<String> generateParentheses(int n) {
        this.n = n;
        res.clear();
        dfs(0, 0);
        return new ArrayList<>(res);
    }

    private void dfs(int opened, int closed) {
        if (path.length() == 2 * n) {
            res.add(path.toString());
            return;
        }
        if (opened < n) { // an opening bracket fits while some are left
            path.append('(');
            dfs(opened + 1, closed);
            path.deleteCharAt(path.length() - 1);
        }
        if (closed < opened) { // a closing bracket needs an unmatched opening one
            path.append(')');
            dfs(opened, closed + 1);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

