def add_operators(num: str, target: int) -> list[str]:
    """Every way to put + - * between the digits of num so it equals target (LC 282)."""
    res = []

    def dfs(i: int, expr: str, value: int, last: int) -> None:
        # value: the expression so far; last: its final term, which a * must take back
        if i == len(num):
            if value == target:
                res.append(expr)
            return
        for j in range(i, len(num)):
            if j > i and num[i] == "0":
                break  # no numbers with a leading zero
            s = num[i : j + 1]
            x = int(s)
            if i == 0:
                dfs(j + 1, s, x, x)
            else:
                dfs(j + 1, expr + "+" + s, value + x, x)
                dfs(j + 1, expr + "-" + s, value - x, -x)
                dfs(j + 1, expr + "*" + s, value - last + last * x, last * x)  # * binds tighter

    dfs(0, "", 0, 0)
    return res

