// Every way to put + - * between the digits of num so it equals target (LC 282).
vector<string> addOperators(const string& num, long long target) {
    vector<string> res;
    // value: the expression so far; last: its final term, which a * must take back
    function<void(size_t, const string&, long long, long long)> dfs = [&](size_t i, const string& expr, long long value, long long last) {
        if (i == num.size()) {
            if (value == target) res.push_back(expr);
            return;
        }
        for (size_t j = i; j < num.size(); j++) {
            if (j > i && num[i] == '0') break;  // no numbers with a leading zero
            string s = num.substr(i, j - i + 1);
            long long x = stoll(s);
            if (i == 0) {
                dfs(j + 1, s, x, x);
            } else {
                dfs(j + 1, expr + "+" + s, value + x, x);
                dfs(j + 1, expr + "-" + s, value - x, -x);
                dfs(j + 1, expr + "*" + s, value - last + last * x, last * x);  // * binds tighter
            }
        }
    };
    dfs(0, "", 0, 0);
    return res;
}

