def exist(board: list[list[str]], word: str) -> bool:
    """Is word spelled by a path of side-adjacent cells, each used at most once? (LC 79)"""
    rows, cols = len(board), len(board[0])

    def dfs(r: int, c: int, k: int) -> bool:  # does board[r][c] start word[k:]?
        if board[r][c] != word[k]:
            return False
        if k == len(word) - 1:
            return True
        board[r][c] = "#"  # used on this path
        found = any(
            0 <= nr < rows and 0 <= nc < cols and dfs(nr, nc, k + 1)
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1))
        )
        board[r][c] = word[k]  # restore on the way back
        return found

    return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

