// Is word spelled by a path of side-adjacent cells, each used at most once? (LC 79)
bool exist(vector<string> board, const string& word) {
    int rows = board.size(), cols = board[0].size();
    function<bool(int, int, int)> dfs = [&](int r, int c, int k) {  // does board[r][c] start word[k..]?
        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] != word[k]) return false;
        if (k == (int)word.size() - 1) return true;
        board[r][c] = '#';  // used on this path
        bool found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
        board[r][c] = word[k];  // restore on the way back
        return found;
    };
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (dfs(r, c, 0)) return true;
    return false;
}

