    private String word;

    // Is word spelled by a path of side-adjacent cells, each used at most once? (LC 79)
    boolean exist(char[][] board, String word) {
        this.board = board;
        this.word = word;
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(r, c, 0)) return true;
        return false;
    }

    // Does board[r][c] start word[k..]?
    private boolean dfs(int r, int c, int k) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] != word.charAt(k)) return false;
        if (k == word.length() - 1) return true;
        board[r][c] = '#'; // used on this path
        boolean found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
        board[r][c] = word.charAt(k); // restore on the way back
        return found;
    }
}

