def solve_sudoku(board: list[list[str]]) -> bool:
    """Fill the '.' cells in place so each row, column and 3x3 box holds 1-9 once (LC 37)."""
    rows, cols, boxes = [0] * 9, [0] * 9, [0] * 9  # bit d set: digit d is used there
    empty = []
    for r in range(9):
        for c in range(9):
            if board[r][c] == ".":
                empty.append((r, c))
            else:
                bit = 1 << int(board[r][c])
                rows[r] |= bit
                cols[c] |= bit
                boxes[r // 3 * 3 + c // 3] |= bit

    def fill(k: int) -> bool:
        if k == len(empty):
            return True
        r, c = empty[k]
        b = r // 3 * 3 + c // 3
        for d in range(1, 10):
            bit = 1 << d
            if (rows[r] | cols[c] | boxes[b]) & bit:
                continue  # d is already in this row, column or box
            rows[r] |= bit
            cols[c] |= bit
            boxes[b] |= bit
            board[r][c] = str(d)
            if fill(k + 1):
                return True
            rows[r] ^= bit  # undo
            cols[c] ^= bit
            boxes[b] ^= bit
        board[r][c] = "."
        return False

    return fill(0)

