// Fill the '.' cells in place so each row, column and 3x3 box holds 1-9 once (LC 37).
bool solveSudoku(vector<string>& board) {
    int rows[9] = {}, cols[9] = {}, boxes[9] = {};  // bit d set: digit d is used there
    vector<pair<int, int>> empty;
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++) {
            if (board[r][c] == '.') {
                empty.push_back({r, c});
                continue;
            }
            int bit = 1 << (board[r][c] - '0');
            rows[r] |= bit;
            cols[c] |= bit;
            boxes[r / 3 * 3 + c / 3] |= bit;
        }
    function<bool(size_t)> fill = [&](size_t k) {
        if (k == empty.size()) return true;
        auto [r, c] = empty[k];
        int b = r / 3 * 3 + c / 3;
        for (int d = 1; d <= 9; d++) {
            int bit = 1 << d;
            if ((rows[r] | cols[c] | boxes[b]) & bit) continue;  // d is already in this row, column or box
            rows[r] |= bit;
            cols[c] |= bit;
            boxes[b] |= bit;
            board[r][c] = char('0' + d);
            if (fill(k + 1)) return true;
            rows[r] ^= bit;  // undo
            cols[c] ^= bit;
            boxes[b] ^= bit;
        }
        board[r][c] = '.';
        return false;
    };
    return fill(0);
}

