class Solution {
    private final int[] rows = new int[9], cols = new int[9], boxes = new int[9]; // bit d set: digit d is used there
    private final List<int[]> empty = new ArrayList<>();
    private char[][] board;

    // Fill the '.' cells in place so each row, column and 3x3 box holds 1-9 once (LC 37).
    boolean solveSudoku(char[][] board) {
        this.board = board;
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    empty.add(new int[] {r, c});
                    continue;
                }
                int bit = 1 << (board[r][c] - '0');
                rows[r] |= bit;
                cols[c] |= bit;
                boxes[r / 3 * 3 + c / 3] |= bit;
            }
        return fill(0);
    }

    private boolean fill(int k) {
        if (k == empty.size()) return true;
        int r = empty.get(k)[0], c = empty.get(k)[1], b = r / 3 * 3 + c / 3;
        for (int d = 1; d <= 9; d++) {
            int bit = 1 << d;
            if (((rows[r] | cols[c] | boxes[b]) & bit) != 0) continue; // d is already in this row, column or box
            rows[r] |= bit;
            cols[c] |= bit;
            boxes[b] |= bit;
            board[r][c] = (char) ('0' + d);
            if (fill(k + 1)) return true;
            rows[r] ^= bit; // undo
            cols[c] ^= bit;
            boxes[b] ^= bit;
        }
        board[r][c] = '.';
        return false;
    }
}

