// solveSudoku fills the '.' cells in place so each row, column and 3x3 box holds 1-9 once (LC 37).
func solveSudoku(board [][]byte) bool {
	var rows, cols, boxes [9]int // bit d set: digit d is used there
	var empty [][2]int
	for r := 0; r < 9; r++ {
		for c := 0; c < 9; c++ {
			if board[r][c] == '.' {
				empty = append(empty, [2]int{r, c})
				continue
			}
			bit := 1 << (board[r][c] - '0')
			rows[r] |= bit
			cols[c] |= bit
			boxes[r/3*3+c/3] |= bit
		}
	}
	var fill func(k int) bool
	fill = func(k int) bool {
		if k == len(empty) {
			return true
		}
		r, c := empty[k][0], empty[k][1]
		b := r/3*3 + c/3
		for d := 1; d <= 9; d++ {
			bit := 1 << d
			if (rows[r]|cols[c]|boxes[b])&bit != 0 {
				continue // d is already in this row, column or box
			}
			rows[r] |= bit
			cols[c] |= bit
			boxes[b] |= bit
			board[r][c] = byte('0' + d)
			if fill(k + 1) {
				return true
			}
			rows[r] ^= bit // undo
			cols[c] ^= bit
			boxes[b] ^= bit
		}
		board[r][c] = '.'
		return false
	}
	return fill(0)
}

