from functools import cache


def num_decodings(s: str) -> int:
    """Ways to read a digit string as letters, 1 = A ... 26 = Z (LC 91)."""

    @cache
    def ways(i: int) -> int:  # ways to decode s[i:]
        if i == len(s):
            return 1
        if s[i] == "0":
            return 0  # no letter's code starts with 0
        total = ways(i + 1)  # read one digit
        if i + 1 < len(s) and int(s[i : i + 2]) <= 26:
            total += ways(i + 2)  # or two
        return total

    return ways(0)

