// Ways to read a digit string as letters, 1 = A ... 26 = Z (LC 91).
long long numDecodings(const string& s) {
    int n = s.size();
    vector<long long> memo(n + 1, -1);  // memo[i]: ways to decode s[i..], -1 = not computed yet
    function<long long(int)> ways = [&](int i) -> long long {
        if (i == n) return 1;
        if (memo[i] >= 0) return memo[i];
        if (s[i] == '0') return memo[i] = 0;  // no letter's code starts with 0
        long long total = ways(i + 1);  // read one digit
        if (i + 1 < n && stoi(s.substr(i, 2)) <= 26) total += ways(i + 2);  // or two
        return memo[i] = total;
    };
    return ways(0);
}

