class Solution {
    private Long[] memo; // memo[i]: ways to decode s[i..], null = not computed yet
    private String s;

    // Ways to read a digit string as letters, 1 = A ... 26 = Z (LC 91).
    long numDecodings(String s) {
        this.s = s;
        memo = new Long[s.length() + 1];
        return ways(0);
    }

    private long ways(int i) {
        if (i == s.length()) return 1;
        if (memo[i] != null) return memo[i];
        long total = 0;
        if (s.charAt(i) != '0') { // no letter's code starts with 0
            total = ways(i + 1); // read one digit
            if (i + 1 < s.length() && Integer.parseInt(s.substring(i, i + 2)) <= 26) total += ways(i + 2); // or two
        }
        return memo[i] = total;
    }
}

