// numDecodings returns the ways to read a digit string as letters, 1 = A ... 26 = Z (LC 91).
func numDecodings(s string) int {
	n := len(s)
	memo := make([]int, n+1) // memo[i]: ways to decode s[i:], -1 = not computed yet
	for i := range memo {
		memo[i] = -1
	}
	var ways func(i int) int
	ways = func(i int) int {
		if i == n {
			return 1
		}
		if memo[i] >= 0 {
			return memo[i]
		}
		total := 0
		if s[i] != '0' { // no letter's code starts with 0
			total = ways(i + 1) // read one digit
			if i+1 < n && (s[i]-'0')*10+(s[i+1]-'0') <= 26 {
				total += ways(i + 2) // or two
			}
		}
		memo[i] = total
		return total
	}
	return ways(0)
}

