// House robber with the houses in a circle: the first and last are neighbours (LC 213).
int robCircle(const vector<int>& nums) {
    auto robLine = [&](int lo, int hi) {  // the plain robber on nums[lo, hi)
        int prev2 = 0, prev1 = 0;
        for (int i = lo; i < hi; i++) {
            int cur = max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    };
    int n = nums.size();
    if (n == 1) return nums[0];
    return max(robLine(0, n - 1), robLine(1, n));  // without the last, or without the first
}

