// Area of the largest all-'1' square; each row is a string such as "10111" (LC 221).
int maximalSquare(const vector<string>& matrix) {
    int cols = matrix[0].size(), best = 0;
    vector<int> dp(cols + 1, 0);  // dp[c + 1]: side of the largest square ending at (r, c); dp[0] stays 0
    for (const string& row : matrix) {
        int diag = 0;  // the up-left neighbour: dp[c] before this row overwrote it
        for (int c = 0; c < cols; c++) {
            int up = dp[c + 1];
            dp[c + 1] = row[c] == '1' ? min({up, dp[c], diag}) + 1 : 0;  // limited by up, left, up-left
            best = max(best, dp[c + 1]);
            diag = up;
        }
    }
    return best * best;
}

