func maximalSquare(matrix []string) int {
	cols, best := len(matrix[0]), 0
	dp := make([]int, cols+1) // dp[c + 1]: side of the largest square ending at (r, c); dp[0] stays 0
	for _, row := range matrix {
		diag := 0 // the up-left neighbour: dp[c] before this row overwrote it
		for c := 0; c < cols; c++ {
			up := dp[c+1]
			if row[c] == '1' {
				dp[c+1] = min(up, dp[c], diag) + 1 // limited by up, left, up-left
			} else {
				dp[c+1] = 0
			}
			best = max(best, dp[c+1])
			diag = up
		}
	}
	return best * best
}

