def min_initial_health(dungeon: list[list[int]]) -> int:
    """Least starting health to reach the bottom-right keeping health >= 1 throughout (LC 174)."""
    rows, cols = len(dungeon), len(dungeon[0])
    need = [float("inf")] * (cols + 1)  # need[c]: least health on entering (r, c)
    need[cols - 1] = 1  # a virtual cell below the goal: arrive there with at least 1
    for r in range(rows - 1, -1, -1):
        for c in range(cols - 1, -1, -1):
            nxt = min(need[c], need[c + 1])  # down (row r + 1's value) or right (already row r)
            need[c] = max(1, nxt - dungeon[r][c])
    return need[0]

