// Can nums be split into two groups with equal sums?
bool canPartition(const vector<int>& nums) {
    int total = accumulate(nums.begin(), nums.end(), 0);
    if (total % 2) return false;
    int target = total / 2;
    vector<char> dp(target + 1, false);  // dp[s]: some subset sums to s
    dp[0] = true;
    for (int x : nums)
        for (int s = target; s >= x; s--)  // backwards: x is used at most once
            dp[s] = dp[s] || dp[s - x];
    return dp[target];
}

