        int[] dp = new int[amount + 1]; // dp[s]: fewest coins for sum s
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int coin : coins)
            for (int s = coin; s <= amount; s++) // forwards: the coin may be reused
