// minCoins returns the fewest coins (each reusable) that sum to amount, or -1.
func minCoins(coins []int, amount int) int {
	inf := amount + 1 // more coins than any answer can need
	dp := make([]int, amount+1) // dp[s]: fewest coins for sum s
	for s := 1; s <= amount; s++ {
		dp[s] = inf
	}
	for _, coin := range coins {
		for s := coin; s <= amount; s++ { // forwards: the coin may be reused
			dp[s] = min(dp[s], dp[s-coin]+1)
		}
	}
	if dp[amount] < inf {
		return dp[amount]
	}
	return -1
}

