def count_lis(nums: list[int]) -> int:
    """Number of longest strictly increasing subsequences (LC 673)."""
    n = len(nums)
    length = [1] * n  # length[i]: longest increasing subsequence ending at i
    count = [1] * n  # count[i]: how many of that length end at i
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                if length[j] + 1 > length[i]:  # longer: take over j's count
                    length[i], count[i] = length[j] + 1, count[j]
                elif length[j] + 1 == length[i]:  # as long: add j's count
                    count[i] += count[j]
    best = max(length)
    return sum(c for l, c in zip(length, count) if l == best)

