// countLis returns the number of longest strictly increasing subsequences (LC 673).
func countLis(nums []int) int {
	n := len(nums)
	length, count := make([]int, n), make([]int, n) // longest ending at i, and how many of that length
	best := 0
	for i := range nums {
		length[i], count[i] = 1, 1
		for j := 0; j < i; j++ {
			if nums[j] >= nums[i] {
				continue
			}
			if length[j]+1 > length[i] { // longer: take over j's count
				length[i], count[i] = length[j]+1, count[j]
			} else if length[j]+1 == length[i] { // as long: add j's count
				count[i] += count[j]
			}
		}
		best = max(best, length[i])
	}
	total := 0
	for i := range nums {
		if length[i] == best {
			total += count[i]
		}
	}
	return total
}

