// Longest subsequence whose neighbours differ by exactly difference (LC 1218).
int longestArithSubseq(const vector<int>& arr, int difference) {
    unordered_map<int, int> bestEnd;  // value -> longest such subsequence ending with that value
    int best = 0;
    for (int x : arr) {
        auto it = bestEnd.find(x - difference);
        int len = (it == bestEnd.end() ? 0 : it->second) + 1;  // extend the one ending at x - difference
        bestEnd[x] = len;
        best = max(best, len);
    }
    return best;
}

