        int best = 0;
        for (int x : arr) {
            int len = bestEnd.getOrDefault(x - difference, 0) + 1; // extend the one ending at x - difference
            bestEnd.put(x, len);
            best = Math.max(best, len);
        }
        return best;
    }
}

