// Can s be cut into dictionary words, each usable any number of times? (LC 139)
bool wordBreak(const string& s, const vector<string>& words) {
    unordered_set<string> vocab(words.begin(), words.end());
    size_t longest = 0;
    for (auto& w : words) longest = max(longest, w.size());
    int n = s.size();
    vector<bool> ok(n + 1, false);  // ok[i]: the prefix s[0, i) can be cut
    ok[0] = true;
    for (int i = 1; i <= n; i++)
        for (int j = max(0, i - (int)longest); j < i && !ok[i]; j++)  // the last word is s[j, i)
            ok[i] = ok[j] && vocab.count(s.substr(j, i - j));
    return ok[n];
}

