class Solution {
    // Can s be cut into dictionary words, each usable any number of times? (LC 139)
    boolean wordBreak(String s, List<String> words) {
        Set<String> vocab = new HashSet<>(words);
        int longest = 0;
        for (String w : words) longest = Math.max(longest, w.length());
        int n = s.length();
        boolean[] ok = new boolean[n + 1]; // ok[i]: the prefix s[0, i) can be cut
        ok[0] = true;
        for (int i = 1; i <= n; i++)
            for (int j = Math.max(0, i - longest); j < i && !ok[i]; j++) // the last word is s[j, i)
                ok[i] = ok[j] && vocab.contains(s.substring(j, i));
        return ok[n];
    }
}

