// wordBreak reports whether s can be cut into dictionary words, each usable any number of times.
func wordBreak(s string, words []string) bool {
	vocab := map[string]bool{}
	longest := 0
	for _, w := range words {
		vocab[w] = true
		longest = max(longest, len(w))
	}
	ok := make([]bool, len(s)+1) // ok[i]: the prefix s[:i] can be cut
	ok[0] = true
	for i := 1; i <= len(s); i++ {
		for j := max(0, i-longest); j < i && !ok[i]; j++ { // the last word is s[j:i]
			ok[i] = ok[j] && vocab[s[j:i]]
		}
	}
	return ok[len(s)]
}

