def num_distinct(s: str, t: str) -> int:
    """How many times t occurs in s as a subsequence (LC 115)."""
    dp = [1] + [0] * len(t)  # dp[j]: ways the part of s read so far forms t[:j]
    for c in s:
        for j in range(len(t), 0, -1):  # backwards: this c is used at most once per match
            if t[j - 1] == c:
                dp[j] += dp[j - 1]
    return dp[len(t)]

