def longest_palindrome(s: str) -> str:
    """Longest palindromic substring, expanding around all 2n - 1 centres (LC 5)."""
    start = end = 0  # the best so far is s[start:end]
    for center in range(2 * len(s) - 1):
        lo, hi = center // 2, (center + 1) // 2  # even centre: a letter; odd: the gap after it
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo, hi = lo - 1, hi + 1
        if hi - lo - 1 > end - start:  # the palindrome found is s[lo+1:hi]
            start, end = lo + 1, hi
    return s[start:end]

