string longestPalindrome(const string& s) {
    int n = s.size(), start = 0, end = 0;  // the best so far is s[start, end)
    for (int center = 0; center < 2 * n - 1; center++) {
        int lo = center / 2, hi = (center + 1) / 2;  // even centre: a letter; odd: the gap after it
        while (lo >= 0 && hi < n && s[lo] == s[hi]) lo--, hi++;
        if (hi - lo - 1 > end - start) start = lo + 1, end = hi;  // the palindrome found is s[lo+1, hi)
    }
    return s.substr(start, end - start);
}

