// Most coins from bursting all balloons (LC 312): pick the last one burst in each range.
int maxCoins(const vector<int>& nums) {
    vector<int> vals{1};
    vals.insert(vals.end(), nums.begin(), nums.end());
    vals.push_back(1);
    int n = vals.size();
    vector<vector<int>> dp(n, vector<int>(n, 0));  // dp[i][j]: best for the balloons strictly between i and j
    for (int i = n - 1; i >= 0; i--)  // i backwards so dp[k][j] with k > i is ready
        for (int j = i + 2; j < n; j++)
            for (int k = i + 1; k < j; k++)  // k goes last: its neighbours are then i and j
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + vals[i] * vals[k] * vals[j]);
    return dp[0][n - 1];
}

