// Largest sum of a non-empty subarray when the array wraps around (LC 918).
int maxCircularSubarray(const vector<int>& nums) {
    int bestMax = nums[0], curMax = nums[0], bestMin = nums[0], curMin = nums[0], total = nums[0];
    for (size_t i = 1; i < nums.size(); i++) {
        int x = nums[i];
        curMax = max(x, curMax + x);  // Kadane for the largest subarray...
        bestMax = max(bestMax, curMax);
        curMin = min(x, curMin + x);  // ...and for the smallest
        bestMin = min(bestMin, curMin);
        total += x;
    }
    // Wrapping = everything but a middle part. All negative: that would be empty, so don't.
    return bestMax > 0 ? max(bestMax, total - bestMin) : bestMax;
}

