func maxCircularSubarray(nums []int) int {
	bestMax, curMax, bestMin, curMin, total := nums[0], nums[0], nums[0], nums[0], nums[0]
	for _, x := range nums[1:] {
		curMax = max(x, curMax+x) // Kadane for the largest subarray...
		bestMax = max(bestMax, curMax)
		curMin = min(x, curMin+x) // ...and for the smallest
		bestMin = min(bestMin, curMin)
		total += x
	}
	// Wrapping = everything but a middle part. All negative: that would be empty, so don't.
	if bestMax > 0 {
		return max(bestMax, total-bestMin)
	}
	return bestMax
