    long long dropped = LLONG_MIN / 2;  // best sum ending here with one element deleted
    for (size_t i = 1; i < arr.size(); i++) {
        long long x = arr[i];
        dropped = max(keep, dropped + x);  // delete x (old keep), or extend an earlier deletion
        keep = max(x, keep + x);
        best = max({best, keep, dropped});
    }
    return best;
}

