func maxSumOneDeletion(arr []int) int {
	keep, best := arr[0], arr[0] // keep: best sum ending here with nothing deleted
	dropped := -1 << 60 // best sum ending here with one element deleted
	for _, x := range arr[1:] {
		dropped = max(keep, dropped+x) // delete x (old keep), or extend an earlier deletion
		keep = max(x, keep+x)
		best = max(best, keep, dropped)
	}
	return best
}

