// Cheapest 1-, 7- and 30-day passes (prices costs) covering every travel day (LC 983).
int minTicketCost(const vector<int>& days, const vector<int>& costs) {
    int last = days.back();
    vector<bool> travel(last + 1, false);
    for (int d : days) travel[d] = true;
    vector<int> dp(last + 1, 0);  // dp[d]: cheapest cover of every travel day up to day d
    for (int d = 1; d <= last; d++) {
        if (!travel[d]) {
            dp[d] = dp[d - 1];  // nothing to cover today
            continue;
        }
        dp[d] = min({dp[d - 1] + costs[0],
                     dp[max(0, d - 7)] + costs[1],  // a 7-day pass ending today covers d-6..d
                     dp[max(0, d - 30)] + costs[2]});
    }
    return dp[last];
}

