// questions[i] = {points, brainpower}; solving i skips the next brainpower ones (LC 2140).
long long mostPoints(const vector<pair<int, int>>& questions) {
    int n = questions.size();
    vector<long long> dp(n + 1, 0);  // dp[i]: best from question i on, filled back to front
    for (int i = n - 1; i >= 0; i--) {
        auto [points, skip] = questions[i];
        dp[i] = max(dp[i + 1], points + dp[min(n, i + skip + 1)]);  // pass on i, or solve it and jump
    }
    return dp[0];
}

