def first_player_wins(nums: list[int]) -> bool:
    """Players take from either end in turn; does the first end with at least as much? (LC 486)"""
    n = len(nums)
    dp = nums[:]  # dp[j] for the current i: best (mover - opponent) on nums[i..j]; i == j: take it
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            dp[j] = max(nums[i] - dp[j], nums[j] - dp[j - 1])  # take the left end, or the right
    return dp[n - 1] >= 0

