// From index 0 to n - 1 in jumps of 1..k steps: the best sum of the values landed on (LC 1696).
long long maxJumpScore(const vector<int>& nums, int k) {
    int n = nums.size();
    vector<long long> dp(n);  // dp[i]: best score landing on i
    dp[0] = nums[0];
    deque<int> dq{0};  // indexes in the last k, dp decreasing: the front is the best place to jump from
    for (int i = 1; i < n; i++) {
        if (dq.front() < i - k) dq.pop_front();  // too far back to reach i
        dp[i] = dp[dq.front()] + nums[i];
        while (!dq.empty() && dp[dq.back()] <= dp[i]) dq.pop_back();  // i is closer and no worse
        dq.push_back(i);
    }
    return dp[n - 1];
}

