class Solution {
    // From index 0 to n - 1 in jumps of 1..k steps: the best sum of the values landed on (LC 1696).
    long maxJumpScore(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n]; // dp[i]: best score landing on i
        dp[0] = nums[0];
        Deque<Integer> dq = new ArrayDeque<>(List.of(0)); // indexes in the last k, dp decreasing
        for (int i = 1; i < n; i++) {
            if (dq.peekFirst() < i - k) dq.pollFirst(); // too far back to reach i
            dp[i] = dp[dq.peekFirst()] + nums[i];
            while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast(); // i is closer and no worse
            dq.offerLast(i);
        }
        return dp[n - 1];
    }
}

