// maxJumpScore: from index 0 to n - 1 in jumps of 1..k steps, the best sum of the values landed on (LC 1696).
func maxJumpScore(nums []int, k int) int {
	n := len(nums)
	dp := make([]int, n) // dp[i]: best score landing on i
	dp[0] = nums[0]
	dq := []int{0} // indexes in the last k, dp decreasing: the front is the best place to jump from
	for i := 1; i < n; i++ {
		if dq[0] < i-k {
			dq = dq[1:] // too far back to reach i
		}
		dp[i] = dp[dq[0]] + nums[i]
		for len(dq) > 0 && dp[dq[len(dq)-1]] <= dp[i] {
			dq = dq[:len(dq)-1] // i is closer and no worse
		}
		dq = append(dq, i)
	}
	return dp[n-1]
}

