    def __init__(self):
        self.inbox: list[int] = []  # new items go on top here
        self.outbox: list[int] = []  # items leave from here, oldest on top

    def push(self, x: int) -> None:
        self.inbox.append(x)

    def _refill(self) -> None:
        if not self.outbox:  # only when empty, or the order breaks
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def pop(self) -> int:
        self._refill()
        return self.outbox.pop()

    def peek(self) -> int:
        self._refill()
        return self.outbox[-1]

    def empty(self) -> bool:
        return not self.inbox and not self.outbox

