// MyQueue is a FIFO queue built from two stacks (LC 232).
type MyQueue struct {
	inbox, outbox []int // new items go on inbox; items leave from outbox, oldest on top
}

func (q *MyQueue) Push(x int) { q.inbox = append(q.inbox, x) }

func (q *MyQueue) refill() {
	if len(q.outbox) == 0 { // only when empty, or the order breaks
		for len(q.inbox) > 0 {
			q.outbox = append(q.outbox, q.inbox[len(q.inbox)-1])
			q.inbox = q.inbox[:len(q.inbox)-1]
		}
	}
}

func (q *MyQueue) Pop() int {
	q.refill()
	x := q.outbox[len(q.outbox)-1]
	q.outbox = q.outbox[:len(q.outbox)-1]
	return x
}

func (q *MyQueue) Peek() int {
	q.refill()
	return q.outbox[len(q.outbox)-1]
}

func (q *MyQueue) Empty() bool { return len(q.inbox) == 0 && len(q.outbox) == 0 }

