import heapq


class MedianFinder:
    """Running median of a stream of numbers (LC 295)."""

    def __init__(self):
        self.low: list[int] = []  # the smaller half, negated so heapq gives a max-heap
        self.high: list[int] = []  # the larger half, a min-heap

    def add(self, x: int) -> None:
        heapq.heappush(self.low, -x)
        heapq.heappush(self.high, -heapq.heappop(self.low))  # the largest of low moves up
        if len(self.high) > len(self.low):  # low keeps the same size or one more
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def median(self) -> float:
        if len(self.low) > len(self.high):
            return -self.low[0]
        return (-self.low[0] + self.high[0]) / 2

