// Running median of a stream of numbers (LC 295).
class MedianFinder {
    priority_queue<int> low;  // the smaller half, largest on top
    priority_queue<int, vector<int>, greater<int>> high;  // the larger half, smallest on top

public:
    void add(int x) {
        low.push(x);
        high.push(low.top());  // the largest of low moves up
        low.pop();
        if (high.size() > low.size()) {  // low keeps the same size or one more
            low.push(high.top());
            high.pop();
        }
    }
    double median() const {
        return low.size() > high.size() ? low.top() : ((double)low.top() + high.top()) / 2;
    }
};

