class MedianFinder {
    private final PriorityQueue<Integer> low = new PriorityQueue<>(Comparator.reverseOrder()); // the smaller half
    private final PriorityQueue<Integer> high = new PriorityQueue<>(); // the larger half

    void add(int x) {
        low.offer(x);
        high.offer(low.poll()); // the largest of low moves up
        if (high.size() > low.size()) low.offer(high.poll()); // low keeps the same size or one more
    }

    double median() {
        return low.size() > high.size() ? low.peek() : ((double) low.peek() + high.peek()) / 2;
    }
