import "container/heap"

// intHeap is a container/heap of ints in the order less gives.
type intHeap struct {
	xs   []int
	less func(a, b int) bool
}

func (h *intHeap) Len() int           { return len(h.xs) }
func (h *intHeap) Less(i, j int) bool { return h.less(h.xs[i], h.xs[j]) }
func (h *intHeap) Swap(i, j int)      { h.xs[i], h.xs[j] = h.xs[j], h.xs[i] }
func (h *intHeap) Push(x any)         { h.xs = append(h.xs, x.(int)) }
func (h *intHeap) Pop() any {
	x := h.xs[len(h.xs)-1]
	h.xs = h.xs[:len(h.xs)-1]
	return x
}

// MedianFinder keeps the running median of a stream of numbers (LC 295).
type MedianFinder struct {
	low, high *intHeap
}

func NewMedianFinder() *MedianFinder {
	return &MedianFinder{
		low:  &intHeap{less: func(a, b int) bool { return a > b }}, // the smaller half, largest on top
		high: &intHeap{less: func(a, b int) bool { return a < b }}, // the larger half, smallest on top
	}
}

func (m *MedianFinder) Add(x int) {
	heap.Push(m.low, x)
	heap.Push(m.high, heap.Pop(m.low)) // the largest of low moves up
	if m.high.Len() > m.low.Len() { // low keeps the same size or one more
		heap.Push(m.low, heap.Pop(m.high))
	}
}

func (m *MedianFinder) Median() float64 {
	if m.low.Len() > m.high.Len() {
		return float64(m.low.xs[0])
	}
	return float64(m.low.xs[0]+m.high.xs[0]) / 2
}

