import random


class RandomizedSet:
    """insert, remove and get_random in O(1) on average (LC 380)."""

    def __init__(self):
        self.items: list[int] = []  # the values, in no particular order
        self.where: dict[int, int] = {}  # value -> its index in items

    def insert(self, x: int) -> bool:
        if x in self.where:
            return False
        self.where[x] = len(self.items)
        self.items.append(x)
        return True

    def remove(self, x: int) -> bool:
        if x not in self.where:
            return False
        i, last = self.where.pop(x), self.items.pop()
        if i < len(self.items):  # x was not last: the last value fills its slot
            self.items[i] = last
            self.where[last] = i
        return True

    def get_random(self) -> int:
        return random.choice(self.items)

