// insert, remove and getRandom in O(1) on average (LC 380).
class RandomizedSet {
    vector<int> items;  // the values, in no particular order
    unordered_map<int, int> where;  // value -> its index in items

public:
    bool insert(int x) {
        if (where.count(x)) return false;
        where[x] = items.size();
        items.push_back(x);
        return true;
    }
    bool remove(int x) {
        auto it = where.find(x);
        if (it == where.end()) return false;
        int i = it->second, last = items.back();
        items[i] = last;  // the last value fills x's slot (x itself if it was last)
        where[last] = i;
        items.pop_back();
        where.erase(x);
        return true;
    }
    int getRandom() const { return items[rand() % items.size()]; }
};

