class RandomizedSet {
    private final List<Integer> items = new ArrayList<>(); // the values, in no particular order
    private final Map<Integer, Integer> where = new HashMap<>(); // value -> its index in items
    private final Random random = new Random();

    boolean insert(int x) {
        if (where.containsKey(x)) return false;
        where.put(x, items.size());
        items.add(x);
        return true;
    }

    boolean remove(int x) {
        Integer i = where.get(x);
        if (i == null) return false;
        int last = items.get(items.size() - 1);
        items.set(i, last); // the last value fills x's slot (x itself if it was last)
        where.put(last, i);
        items.remove(items.size() - 1);
        where.remove(x);
        return true;
    }

    int getRandom() {
        return items.get(random.nextInt(items.size()));
    }
}

