import "math/rand"

// RandomizedSet supports Insert, Remove and GetRandom in O(1) on average (LC 380).
type RandomizedSet struct {
	items []int       // the values, in no particular order
	where map[int]int // value -> its index in items
}

func NewRandomizedSet() *RandomizedSet { return &RandomizedSet{where: map[int]int{}} }

func (s *RandomizedSet) Insert(x int) bool {
	if _, ok := s.where[x]; ok {
		return false
	}
	s.where[x] = len(s.items)
	s.items = append(s.items, x)
	return true
}

func (s *RandomizedSet) Remove(x int) bool {
	i, ok := s.where[x]
	if !ok {
		return false
	}
	last := s.items[len(s.items)-1]
	s.items[i] = last // the last value fills x's slot (x itself if it was last)
	s.where[last] = i
	s.items = s.items[:len(s.items)-1]
	delete(s.where, x)
	return true
}

func (s *RandomizedSet) GetRandom() int { return s.items[rand.Intn(len(s.items))] }

