class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def serialize(root) -> str:
    """Preorder with '#' for each missing child, comma-separated (LC 297)."""
    out = []

    def walk(node) -> None:
        if not node:
            out.append("#")
            return
        out.append(str(node.val))
        walk(node.left)
        walk(node.right)

    walk(root)
    return ",".join(out)


def deserialize(data: str):
    """The tree serialize() wrote: the tokens are read back in the same preorder."""
    tokens = iter(data.split(","))

    def build():
        t = next(tokens)
        if t == "#":
            return None
        node = TreeNode(int(t))
        node.left = build()  # left before right, as they were written
        node.right = build()
        return node

    return build()

