    TreeNode *left, *right;
    TreeNode(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) : val(v), left(l), right(r) {}
};

// Preorder with '#' for each missing child, comma-separated (LC 297).
string serialize(TreeNode* root) {
    if (!root) return "#";
    return to_string(root->val) + "," + serialize(root->left) + "," + serialize(root->right);
}

// The tree serialize() wrote: the tokens are read back in the same preorder.
TreeNode* deserialize(const string& data) {
    size_t pos = 0;
    function<TreeNode*()> build = [&]() -> TreeNode* {
        size_t end = data.find(',', pos);
        if (end == string::npos) end = data.size();
        string t = data.substr(pos, end - pos);
        pos = end + 1;
        if (t == "#") return nullptr;
        TreeNode* node = new TreeNode(stoi(t));
        node->left = build();  // left before right, as they were written
        node->right = build();
        return node;
    };
    return build();
}

