class Codec {
    private String[] tokens;
    private int next;

    // Preorder with '#' for each missing child, comma-separated (LC 297).
    String serialize(TreeNode root) {
        if (root == null) return "#";
        return root.val + "," + serialize(root.left) + "," + serialize(root.right);
    }

    // The tree serialize() wrote: the tokens are read back in the same preorder.
    TreeNode deserialize(String data) {
        tokens = data.split(",");
        next = 0;
        return build();
    }

    private TreeNode build() {
        String t = tokens[next++];
        if (t.equals("#")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(t));
        node.left = build(); // left before right, as they were written
        node.right = build();
        return node;
    }
}

