import (
	"strconv"
	"strings"
)

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

// serialize writes the tree in preorder with "#" for each missing child, comma-separated (LC 297).
func serialize(root *TreeNode) string {
	if root == nil {
		return "#"
	}
	return strconv.Itoa(root.Val) + "," + serialize(root.Left) + "," + serialize(root.Right)
}

// deserialize rebuilds the tree serialize wrote, reading the tokens back in the same preorder.
func deserialize(data string) *TreeNode {
	tokens := strings.Split(data, ",")
	next := 0
	var build func() *TreeNode
	build = func() *TreeNode {
		t := tokens[next]
		next++
		if t == "#" {
			return nil
		}
		v, _ := strconv.Atoi(t)
		node := &TreeNode{Val: v}
		node.Left = build() // left before right, as they were written
		node.Right = build()
		return node
	}
	return build()
}

