class MagicDictionary:
    """Does a word differ from some dictionary word in exactly one letter? (LC 676)"""

    def __init__(self, words: list[str]):
        self.root: dict = {}  # a trie of nested dicts; "$" marks the end of a word
        for w in words:
            node = self.root
            for ch in w:
                node = node.setdefault(ch, {})
            node["$"] = True

    def search(self, word: str) -> bool:
        def dfs(node: dict, i: int, changed: bool) -> bool:
            if i == len(word):
                return changed and "$" in node  # exactly one change, ending on a word
            for ch, child in node.items():
                if ch == "$":
                    continue
                if ch == word[i]:
                    if dfs(child, i + 1, changed):
                        return True
                elif not changed and dfs(child, i + 1, True):  # spend the one change here
                    return True
            return False

        return dfs(self.root, 0, False)

