// Does a word differ from some dictionary word in exactly one letter? (LC 676)
class MagicDictionary {
    struct Node {
        Node* next[26] = {};
        bool end = false;  // a dictionary word ends here
    };
    Node root;

    bool dfs(const Node* node, const string& word, size_t i, bool changed) const {
        if (i == word.size()) return changed && node->end;  // exactly one change, ending on a word
        for (int c = 0; c < 26; c++) {
            const Node* child = node->next[c];
            if (!child) continue;
            if (c == word[i] - 'a') {
                if (dfs(child, word, i + 1, changed)) return true;
            } else if (!changed && dfs(child, word, i + 1, true)) {  // spend the one change here
                return true;
            }
        }
        return false;
    }

public:
    explicit MagicDictionary(const vector<string>& words) {
        for (const string& w : words) {
            Node* node = &root;
            for (char ch : w) {
                if (!node->next[ch - 'a']) node->next[ch - 'a'] = new Node();
                node = node->next[ch - 'a'];
            }
            node->end = true;
        }
    }
    bool search(const string& word) const { return dfs(&root, word, 0, false); }
};

