// Does a word differ from some dictionary word in exactly one letter? (LC 676)
class MagicDictionary {
    private static class Node {
        final Node[] next = new Node[26];
        boolean end; // a dictionary word ends here
    }

    private final Node root = new Node();

    MagicDictionary(String[] words) {
        for (String w : words) {
            Node node = root;
            for (char ch : w.toCharArray()) {
                if (node.next[ch - 'a'] == null) node.next[ch - 'a'] = new Node();
                node = node.next[ch - 'a'];
            }
            node.end = true;
        }
    }

    boolean search(String word) {
        return dfs(root, word, 0, false);
    }

    private boolean dfs(Node node, String word, int i, boolean changed) {
        if (i == word.length()) return changed && node.end; // exactly one change, ending on a word
        for (int c = 0; c < 26; c++) {
            Node child = node.next[c];
            if (child == null) continue;
            if (c == word.charAt(i) - 'a') {
                if (dfs(child, word, i + 1, changed)) return true;
            } else if (!changed && dfs(child, word, i + 1, true)) { // spend the one change here
                return true;
            }
        }
        return false;
    }
}

