type trieNode struct {
	next [26]*trieNode
	end  bool // a dictionary word ends here
}

// MagicDictionary answers whether a word differs from some dictionary word in exactly one letter (LC 676).
type MagicDictionary struct {
	root *trieNode
}

func NewMagicDictionary(words []string) *MagicDictionary {
	root := &trieNode{}
	for _, w := range words {
		node := root
		for i := 0; i < len(w); i++ {
			c := w[i] - 'a'
			if node.next[c] == nil {
				node.next[c] = &trieNode{}
			}
			node = node.next[c]
		}
		node.end = true
	}
	return &MagicDictionary{root}
}

func (d *MagicDictionary) Search(word string) bool {
	var dfs func(node *trieNode, i int, changed bool) bool
	dfs = func(node *trieNode, i int, changed bool) bool {
		if i == len(word) {
			return changed && node.end // exactly one change, ending on a word
		}
		for c, child := range node.next {
			if child == nil {
				continue
			}
			if byte(c) == word[i]-'a' {
				if dfs(child, i+1, changed) {
					return true
				}
			} else if !changed && dfs(child, i+1, true) { // spend the one change here
				return true
			}
		}
		return false
	}
	return dfs(d.root, 0, false)
}

