def count_primes(n: int) -> int:
    """Number of primes below n (LC 204)."""
    if n < 3:
        return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    i = 2
    while i * i < n:
        if is_prime[i]:
            for j in range(i * i, n, i):  # smaller multiples are already crossed out
                is_prime[j] = False
        i += 1
    return sum(is_prime)

