// Number of primes below n (LC 204).
int countPrimes(int n) {
    if (n < 3) return 0;
    vector<bool> isPrime(n, true);
    isPrime[0] = isPrime[1] = false;
    for (long long i = 2; i * i < n; i++)
        if (isPrime[i])
            for (long long j = i * i; j < n; j += i) isPrime[j] = false;  // smaller multiples are already crossed out
    return count(isPrime.begin(), isPrime.end(), true);
}

