class Solution {
    // Number of primes below n (LC 204).
    int countPrimes(int n) {
        if (n < 3) return 0;
        boolean[] composite = new boolean[n]; // composite[k]: k has a smaller prime factor
        int count = 0;
        for (long i = 2; i < n; i++) {
            if (composite[(int) i]) continue;
            count++;
            for (long j = i * i; j < n; j += i) composite[(int) j] = true; // smaller multiples are already crossed out
        }
        return count;
    }
}

