// countPrimes returns the number of primes below n (LC 204).
func countPrimes(n int) int {
	if n < 3 {
		return 0
	}
	composite := make([]bool, n) // composite[k]: k has a smaller prime factor
	count := 0
	for i := 2; i < n; i++ {
		if composite[i] {
			continue
		}
		count++
		for j := i * i; j < n; j += i { // smaller multiples are already crossed out
			composite[j] = true
		}
	}
	return count
}

