def single_numbers(nums: list[int]) -> list[int]:
    """The two values that appear once when every other value appears twice (LC 260), smaller first."""
    xor = 0
    for x in nums:
        xor ^= x  # pairs cancel: xor == a ^ b, nonzero because a != b
    low = xor & -xor  # the lowest bit where a and b differ
    a = b = 0
    for x in nums:
        if x & low:  # that bit splits a and b into different groups; pairs stay together
            a ^= x
        else:
            b ^= x
    return sorted([a, b])

