// The two values that appear once when every other value appears twice (LC 260), smaller first.
vector<int> singleNumbers(const vector<int>& nums) {
    unsigned xr = 0;
    for (int x : nums) xr ^= x;  // pairs cancel: xr == a ^ b, nonzero because a != b
    unsigned low = xr & (0u - xr);  // the lowest bit where a and b differ (unsigned: no overflow)
    int a = 0, b = 0;
    for (int x : nums) {
        if (x & low) a ^= x;  // that bit splits a and b into different groups; pairs stay together
        else b ^= x;
    }
    return {min(a, b), max(a, b)};
}

