class Solution {
    // The two values that appear once when every other value appears twice (LC 260), smaller first.
    int[] singleNumbers(int[] nums) {
        int xor = 0;
        for (int x : nums) xor ^= x; // pairs cancel: xor == a ^ b, nonzero because a != b
        int low = xor & -xor; // the lowest bit where a and b differ
        int a = 0, b = 0;
        for (int x : nums) {
            if ((x & low) != 0) a ^= x; // that bit splits a and b into different groups; pairs stay together
            else b ^= x;
        }
        return new int[] {Math.min(a, b), Math.max(a, b)};
    }
}

