// singleNumbers returns the two values that appear once when every other value appears twice, smaller first.
func singleNumbers(nums []int) []int {
	xor := 0
	for _, x := range nums {
		xor ^= x // pairs cancel: xor == a ^ b, nonzero because a != b
	}
	low := xor & -xor // the lowest bit where a and b differ
	a, b := 0, 0
	for _, x := range nums {
		if x&low != 0 { // that bit splits a and b into different groups; pairs stay together
			a ^= x
		} else {
			b ^= x
		}
	}
	return []int{min(a, b), max(a, b)}
}
